            api.utils.requiredParamChecker(api, connection, ["fileName"]);

            if (connection.error === null) {
                fileName = connection.params.fileName;
            }
        } else {
            fileName = connection.params.fileName;
        }

        fileName = path.normalize(api.configData.general.flatFileDirectory + fileName);

        if (fileName.indexOf(path.normalize(api.configData.general.flatFileDirectory)) === 0) {
            if (connection.error === null) {
                api.fileServer.followFileToServe(api, fileName, connection, next);
            }
        } else
            api.fileServer.sendFileNotFound(api, connection, next);
    };

    api.fileServer.followFileToServe = function(api, fileName, connection, next) {
        api.fs.stat(fileName, function(err, stats) {
            if (err != null) {
                api.fileServer.sendFileNotFound(api, connection, next);
            } else {
                if (stats.isDirectory()) {
                    if (fileName[fileName.length - 1] != "/") {
                        fileName += "/";
                    }

                    api.fileServer.followFileToServe(
                        api,
                        fileName + api.configData.commonWeb.directoryFileType,
                        connection,
                        next
                    );
                } else if (stats.isSymbolicLink()) {
                    api.fs.readLink(fileName, function(err, truePath) {
                        if (err != null) {
                            api.fileServer.sendFileNotFound(api, connection, next);
                        } else {
                            api.fileServer.followFileToServe(api, truePath, connection, next);
                        }
                    });
                } else if (stats.isFile()) {
                    api.fileServer.sendFile(api, fileName, connection, next);
                } else {
                    api.fileServer.sendFileNotFound(api, connection, next);
                }
            }
        });
    };

    api.fileServer.sendFile = function(api, file, connection, next) {
        api.fs.readFile(file, function(err, data) {
            if (err) {
                api.log("error reading: " + file, "red");
            } else {
                if (connection.req != null) {
                    connection.responseHeaders.push(["Content-Type", api.mime.lookup(file)]);

                    connection.responseHeaders.push(["Expires", new Date(
                        new Date().getTime() + api.configData.commonWeb.flatFileCacheDuration * 1000
                    ).toUTCString()]);

                    connection.responseHeaders.push([
                        "Cache-Control",
                        "max-age=" + api.configData.commonWeb.flatFileCacheDuration + ", must-revalidate"
                    ]);

                    api.webServer.cleanHeaders(api, connection);
                    connection.res.writeHead(200, connection.responseHeaders);
                    connection.res.end(data);
                } else {
                    try {
                        connection.write(data + "\r\n");
                        connection.messageCount++;
                    } catch (e) {}
                }

                if (api.configData.log.logRequests) {
                    let full_url = null;
                    let duration = null;
                    let type = null;

                    if (connection.req != null && connection.req.headers != null) {
                        full_url = connection.req.headers.host + connection.req.url;
                        duration = new Date().getTime() - connection.timer.startTime;
                        type = "web";
                    } else {
                        type = "socket";
                        full_url = type;
                        duration = type;
                    }

                    api.logJSON({
                        label: "file @ " + type,
                        to: connection.remoteIP,
                        file: file,
                        request: full_url,
                        size: data.length,
                        duration: duration
                    }, "grey");
                }
            }

            process.nextTick(function() {
                next(connection, false);
            });
        });
    };

    api.fileServer.sendFileNotFound = function(api, connection, next) {
        if (connection.req != null) {
            connection.responseHeaders.push(["Content-Type", "text/html"]);
            api.webServer.cleanHeaders(api, connection);
            connection.res.writeHead(404, connection.responseHeaders);
            connection.res.end(api.configData.general.flatFileNotFoundMessage);
            next(connection, false);
        } else {
            if (connection.error === null) {
                connection.error = new Error("The file, " + connection.params.fileName + ", is not found.");
            }

            next(connection, true);
        }
    };

    next();
}

function $CompileProvider($provide) {
    const hasDirectives = {};
    const Suffix = "Directive";
    const COMMENT_DIRECTIVE_REGEXP = /^\s*directive\:\s*([\d\w\-_]+)\s+(.*)$/;
    const CLASS_DIRECTIVE_REGEXP = /(([\d\w\-_]+)(?:\:([^;]+))?;?)/;
    let urlSanitizationWhitelist = /^\s*(https?|ftp|mailto|file):/;

    this.directive = function registerDirective(name, directiveFactory) {
        if (isString(name)) {
            assertArg(directiveFactory, "directiveFactory");

            if (!hasDirectives.hasOwnProperty(name)) {
                hasDirectives[name] = [];

                $provide.factory(
                    name + Suffix,
                    ["$injector", "$exceptionHandler", function($injector, $exceptionHandler) {
                        const directives = [];

                        forEach(hasDirectives[name], function(directiveFactory) {
                            try {
                                let directive = $injector.invoke(directiveFactory);

                                if (isFunction(directive)) {
                                    directive = {
                                        compile: valueFn(directive)
                                    };
                                } else if (!directive.compile && directive.link) {
                                    directive.compile = valueFn(directive.link);
                                }

                                directive.priority = directive.priority || 0;
                                directive.name = directive.name || name;
                                directive.require = directive.require || (directive.controller && directive.name);
                                directive.restrict = directive.restrict || "A";
                                directives.push(directive);
                            } catch (e) {
                                $exceptionHandler(e);
                            }
                        });

                        return directives;
                    }]
                );
            }

            hasDirectives[name].push(directiveFactory);
        } else {
            forEach(name, reverseParams(registerDirective));
        }

        return this;
    };

    this.urlSanitizationWhitelist = function(regexp) {
        if (isDefined(regexp)) {
            urlSanitizationWhitelist = regexp;
            return this;
        }

        return urlSanitizationWhitelist;
    };

    this.$get = [
        "$injector",
        "$interpolate",
        "$exceptionHandler",
        "$http",
        "$templateCache",
        "$parse",
        "$controller",
        "$rootScope",
        "$document",
        function(
            $injector,
            $interpolate,
            $exceptionHandler,
            $http,
            $templateCache,
            $parse,
            $controller,
            $rootScope,
            $document
        ) {
            const Attributes = function(element, attr) {
                this.$$element = element;
                this.$attr = attr || {};
            };

            Attributes.prototype = {
                $normalize: directiveNormalize,

                $set: function(key, value, writeAttr, attrName) {
                    const booleanKey = getBooleanAttrName(this.$$element[0], key);
                    const $$observers = this.$$observers;
                    let normalizedVal;
                    let nodeName;

                    if (booleanKey) {
                        this.$$element.prop(key, value);
                        attrName = booleanKey;
                    }

                    this[key] = value;

                    if (attrName) {
                        this.$attr[key] = attrName;
                    } else {
                        attrName = this.$attr[key];

                        if (!attrName) {
                            this.$attr[key] = attrName = snake_case(key, "-");
                        }
                    }

                    nodeName = nodeName_(this.$$element);

                    if ((nodeName === "A" && key === "href") || (nodeName === "IMG" && key === "src")) {
                        urlSanitizationNode.setAttribute("href", value);
                        normalizedVal = urlSanitizationNode.href;

                        if (!normalizedVal.match(urlSanitizationWhitelist)) {
                            this[key] = value = "unsafe:" + normalizedVal;
                        }
                    }

                    if (writeAttr !== false) {
                        if (value === null || value === undefined) {
                            this.$$element.removeAttr(attrName);
                        } else {
                            this.$$element.attr(attrName, value);
                        }
                    }

                    $$observers && forEach($$observers[key], function(fn) {
                        try {
                            fn(value);
                        } catch (e) {
                            $exceptionHandler(e);
                        }
                    });
                },

                $observe: function(key, fn) {
                    const attrs = this;
                    const $$observers = attrs.$$observers || (attrs.$$observers = {});
                    const listeners = $$observers[key] || ($$observers[key] = []);
                    listeners.push(fn);

                    $rootScope.$evalAsync(function() {
                        if (!listeners.$$inter) {
                            fn(attrs[key]);
                        }
                    });

                    return fn;
                }
            };

            var urlSanitizationNode = $document[0].createElement("a");
            const startSymbol = $interpolate.startSymbol();
            const endSymbol = $interpolate.endSymbol();

            const denormalizeTemplate = startSymbol == "{{" || endSymbol == "}}" ? identity : function denormalizeTemplate(template) {
                return template.replace(/\{\{/g, startSymbol).replace(/}}/g, endSymbol);
            };

            const NG_ATTR_BINDING = /^ngAttr[A-Z]/;
            return compile;

            function compile($compileNodes, transcludeFn, maxPriority) {
                if (!($compileNodes instanceof jqLite)) {
                    $compileNodes = jqLite($compileNodes);
                }

                const tempParent = document.createDocumentFragment();

                forEach($compileNodes, function(node, index) {
                    if (node.nodeType == 3 && node.nodeValue.match(/\S+/)) {
                        $compileNodes[index] = node = jqLite(node).wrap("<span></span>").parent()[0];
                    }
                });

                const compositeLinkFn = compileNodes($compileNodes, transcludeFn, $compileNodes, maxPriority);

                return function publicLinkFn(scope, cloneConnectFn) {
                    assertArg(scope, "scope");
                    const $linkNode = cloneConnectFn ? JQLitePrototype.clone.call($compileNodes) : $compileNodes;

                    for (let i = 0, ii = $linkNode.length; i < ii; i++) {
                        const node = $linkNode[i];

                        if (node.nodeType == 1 || node.nodeType == 9) {
                            $linkNode.eq(i).data("$scope", scope);
                        }
                    }

                    safeAddClass($linkNode, "ng-scope");

                    if (cloneConnectFn)
                        cloneConnectFn($linkNode, scope);

                    if (compositeLinkFn)
                        compositeLinkFn(scope, $linkNode, $linkNode);

                    return $linkNode;
                };
            }

            function safeAddClass($element, className) {
                try {
                    $element.addClass(className);
                } catch (e) {}
            }

            function compileNodes(nodeList, transcludeFn, $rootElement, maxPriority) {
                const linkFns = [];
                let nodeLinkFn;
                let childLinkFn;
                let directives;
                let attrs;
                let linkFnFound;

                for (let i = 0; i < nodeList.length; i++) {
                    attrs = new Attributes();
                    directives = collectDirectives(nodeList[i], [], attrs, i == 0 ? maxPriority : undefined);
                    nodeLinkFn = directives.length ? applyDirectivesToNode(directives, nodeList[i], attrs, transcludeFn, $rootElement) : null;
                    childLinkFn = (nodeLinkFn && nodeLinkFn.terminal) || !nodeList[i].childNodes || !nodeList[i].childNodes.length ? null : compileNodes(nodeList[i].childNodes, nodeLinkFn ? nodeLinkFn.transclude : transcludeFn);
                    linkFns.push(nodeLinkFn);
                    linkFns.push(childLinkFn);
                    linkFnFound = linkFnFound || nodeLinkFn || childLinkFn;
                }

                return linkFnFound ? compositeLinkFn : null;

                function compositeLinkFn(scope, nodeList, $rootElement, boundTranscludeFn) {
                    let nodeLinkFn;
                    let childLinkFn;
                    let node;
                    let childScope;
                    let childTranscludeFn;
                    let i;
                    let ii;
                    let n;
                    const stableNodeList = [];

                    for (i = 0, ii = nodeList.length; i < ii; i++) {
                        stableNodeList.push(nodeList[i]);
                    }

                    for (i = 0, n = 0, ii = linkFns.length; i < ii; n++) {
                        node = stableNodeList[n];
                        nodeLinkFn = linkFns[i++];
                        childLinkFn = linkFns[i++];

                        if (nodeLinkFn) {
                            if (nodeLinkFn.scope) {
                                childScope = scope.$new(isObject(nodeLinkFn.scope));
                                jqLite(node).data("$scope", childScope);
                            } else {
                                childScope = scope;
                            }

                            childTranscludeFn = nodeLinkFn.transclude;

                            if (childTranscludeFn || (!boundTranscludeFn && transcludeFn)) {
                                nodeLinkFn(childLinkFn, childScope, node, $rootElement, (function(transcludeFn) {
                                    return function(cloneFn) {
                                        const transcludeScope = scope.$new();
                                        transcludeScope.$$transcluded = true;
                                        return transcludeFn(transcludeScope, cloneFn).on("$destroy", bind(transcludeScope, transcludeScope.$destroy));
                                    };
                                })(childTranscludeFn || transcludeFn));
                            } else {
                                nodeLinkFn(childLinkFn, childScope, node, undefined, boundTranscludeFn);
                            }
                        } else if (childLinkFn) {
                            childLinkFn(scope, node.childNodes, undefined, boundTranscludeFn);
                        }
                    }
                }
            }

            function collectDirectives(node, directives, attrs, maxPriority) {
                const nodeType = node.nodeType;
                const attrsMap = attrs.$attr;
                let match;
                let className;

                switch (nodeType) {
                case 1:
                    addDirective(
                        directives,
                        directiveNormalize(nodeName_(node).toLowerCase()),
                        "E",
                        maxPriority
                    );

                    for (var attr, name, nName, ngAttrName, value, nAttrs = node.attributes, j = 0, jj = nAttrs && nAttrs.length; j < jj; j++) {
                        var attrStartName;
                        var attrEndName;
                        var index;
                        attr = nAttrs[j];

                        if (attr.specified) {
                            name = attr.name;
                            ngAttrName = directiveNormalize(name);

                            if (NG_ATTR_BINDING.test(ngAttrName)) {
                                name = ngAttrName.substr(6).toLowerCase();
                            }

                            if ((index = ngAttrName.lastIndexOf("Start")) != -1 && index == ngAttrName.length - 5) {
                                attrStartName = name;
                                attrEndName = name.substr(0, name.length - 5) + "end";
                                name = name.substr(0, name.length - 6);
                            }

                            nName = directiveNormalize(name.toLowerCase());
                            attrsMap[nName] = name;

                            attrs[nName] = value = trim(
                                msie && name == "href" ? decodeURIComponent(node.getAttribute(name, 2)) : attr.value
                            );

                            if (getBooleanAttrName(node, nName)) {
                                attrs[nName] = true;
                            }

                            addAttrInterpolateDirective(node, directives, value, nName);
                            addDirective(directives, nName, "A", maxPriority, attrStartName, attrEndName);
                        }
                    }

                    className = node.className;

                    if (isString(className) && className !== "") {
                        while ((match = CLASS_DIRECTIVE_REGEXP.exec(className))) {
                            nName = directiveNormalize(match[2]);

                            if (addDirective(directives, nName, "C", maxPriority)) {
                                attrs[nName] = trim(match[3]);
                            }

                            className = className.substr(match.index + match[0].length);
                        }
                    }

                    break;
                case 3:
                    addTextInterpolateDirective(directives, node.nodeValue);
                    break;
                case 8:
                    try {
                        match = COMMENT_DIRECTIVE_REGEXP.exec(node.nodeValue);

                        if (match) {
                            nName = directiveNormalize(match[1]);

                            if (addDirective(directives, nName, "M", maxPriority)) {
                                attrs[nName] = trim(match[2]);
                            }
                        }
                    } catch (e) {}

                    break;
                }

                directives.sort(byPriority);
                return directives;
            }

            function groupScan(node, attrStart, attrEnd) {
                const nodes = [];
                let depth = 0;

                if (attrStart && node.hasAttribute && node.hasAttribute(attrStart)) {
                    const startNode = node;

                    do {
                        if (!node) {
                            throw $compileMinErr(
                                "utrat",
                                "Unterminated attribute, found '{0}' but no matching '{1}' found.",
                                attrStart,
                                attrEnd
                            );
                        }

                        if (node.nodeType == 1) {
                            if (node.hasAttribute(attrStart))
                                depth++;

                            if (node.hasAttribute(attrEnd))
                                depth--;
                        }

                        nodes.push(node);
                        node = node.nextSibling;
                    } while (depth > 0);
                } else {
                    nodes.push(node);
                }

                return jqLite(nodes);
            }

            function groupElementsLinkFnWrapper(linkFn, attrStart, attrEnd) {
                return function(scope, element, attrs, controllers) {
                    element = groupScan(element[0], attrStart, attrEnd);
                    return linkFn(scope, element, attrs, controllers);
                };
            }

            function applyDirectivesToNode(directives, compileNode, templateAttrs, transcludeFn, jqCollection) {
                let terminalPriority = -Number.MAX_VALUE;
                const preLinkFns = [];
                const postLinkFns = [];
                let newScopeDirective = null;
                let newIsolateScopeDirective = null;
                let templateDirective = null;
                let $compileNode = (templateAttrs.$$element = jqLite(compileNode));
                let directive;
                let directiveName;
                let $template;
                let transcludeDirective;
                let childTranscludeFn = transcludeFn;
                let controllerDirectives;
                let linkFn;
                let directiveValue;

                for (let i = 0, ii = directives.length; i < ii; i++) {
                    directive = directives[i];
                    const attrStart = directive.$$start;
                    const attrEnd = directive.$$end;

                    if (attrStart) {
                        $compileNode = groupScan(compileNode, attrStart, attrEnd);
                    }

                    $template = undefined;

                    if (terminalPriority > directive.priority) {
                        break;
                    }

                    if ((directiveValue = directive.scope)) {
                        assertNoDuplicate("isolated scope", newIsolateScopeDirective, directive, $compileNode);

                        if (isObject(directiveValue)) {
                            safeAddClass($compileNode, "ng-isolate-scope");
                            newIsolateScopeDirective = directive;
                        }

                        safeAddClass($compileNode, "ng-scope");
                        newScopeDirective = newScopeDirective || directive;
                    }

                    directiveName = directive.name;

                    if ((directiveValue = directive.controller)) {
                        controllerDirectives = controllerDirectives || {};

                        assertNoDuplicate(
                            "'" + directiveName + "' controller",
                            controllerDirectives[directiveName],
                            directive,
                            $compileNode
                        );

                        controllerDirectives[directiveName] = directive;
                    }

                    if ((directiveValue = directive.transclude)) {
                        assertNoDuplicate("transclusion", transcludeDirective, directive, $compileNode);
                        transcludeDirective = directive;
                        terminalPriority = directive.priority;

                        if (directiveValue == "element") {
                            $template = groupScan(compileNode, attrStart, attrEnd);

                            $compileNode = templateAttrs.$$element = jqLite(
                                document.createComment(" " + directiveName + ": " + templateAttrs[directiveName] + " ")
                            );

                            compileNode = $compileNode[0];
                            replaceWith(jqCollection, jqLite(sliceArgs($template)), compileNode);
                            childTranscludeFn = compile($template, transcludeFn, terminalPriority);
                        } else {
                            $template = jqLite(JQLiteClone(compileNode)).contents();
                            $compileNode.html("");
                            childTranscludeFn = compile($template, transcludeFn);
                        }
                    }

                    if (directive.template) {
                        assertNoDuplicate("template", templateDirective, directive, $compileNode);
                        templateDirective = directive;
                        directiveValue = isFunction(directive.template) ? directive.template($compileNode, templateAttrs) : directive.template;
                        directiveValue = denormalizeTemplate(directiveValue);

                        if (directive.replace) {
                            $template = jqLite("<div>" + trim(directiveValue) + "</div>").contents();
                            compileNode = $template[0];

                            if ($template.length != 1 || compileNode.nodeType !== 1) {
                                throw $compileMinErr(
                                    "tplrt",
                                    "Template for directive '{0}' must have exactly one root element. {1}",
                                    directiveName,
                                    ""
                                );
                            }

                            replaceWith(jqCollection, $compileNode, compileNode);

                            const newTemplateAttrs = {
                                $attr: {}
                            };

