            if (err.details) {
                const queue = [err.details];

                while (queue.length) {
                    for (const item of queue[0]) {
                        this.createAnnotation(annotations.VALIDATION_ERROR, item.path, item.message);

                        if (item.inner) {
                            queue.push(item.inner);
                        }
                    }

                    queue.shift();
