        dispatch = function(req, res) {
            let final_dispatch;
            let nsr_sid;

            final_dispatch = function(req, res) {
                let args;
                let home_page;
                let homes;
                let i;
                let index;
                let j;
                let len1;
                let len2;
                let m;
                let method;
                let param;
                let parsed;
                let pathname;
                let ref;
                let route;
                let selected_method;
                let send_static_home;
                parsed = urlparse(req.url);
                pathname = parsed.pathname;

                if (pathname.split("/").length > 2) {
                    pathname = pathname.replace(/\/$/, "");
                }

                req.get = parsed.query != null ? querystring.parse(parsed.query) : {};
                req.body = _extend({}, req.get);
                method = req.method.toLowerCase();

                if (dispatch.logging) {
                    dispatch.log(
                        dispatch.getRemoteAddress(req) + " - [" + new Date().toLocaleString() + "] - " + method.toUpperCase() + " " + pathname + " - HTTP " + req.httpVersion
                    );
                }

                if (dispatch.routes[method]) {
                    selected_method = dispatch.routes[method].concat(dispatch.routes["any"]);
                } else {
                    selected_method = dispatch.routes["any"];
                }

                for (i = 0, len1 = selected_method.length; i < len1; i++) {
                    route = selected_method[i];
                    m = pathname.match(route.pattern);

                    if (m !== null) {
                        if (route.params) {
                            req.params = {};
                            args = m.slice(1);
                            ref = route.params;

                            for (index = j = 0, len2 = ref.length; j < len2; index = ++j) {
                                param = ref[index];
                                req.params[param] = args[index];
                            }
                        }

                        return route.handler(req, res);
                    }
                }

                if (pathname === "/") {
                    homes = (function() {
                        let l;
                        let len3;
                        let ref1;
                        let results;
                        ref1 = dispatch.default_home;
                        results = [];

                        for (l = 0, len3 = ref1.length; l < len3; l++) {
                            home_page = ref1[l];
                            results.push("" + dispatch.static_route + path_tools.sep + home_page);
                        }

                        return results;
                    })();

                    send_static_home = function(candidates) {
                        if (candidates.length === 0) {
                            if (dispatch.list_dir) {
                                return dispatch.directory(dispatch.static_route, ".", res);
                            } else {
                                return dispatch._404(req, res, pathname);
                            }
                        } else {
                            return fs.exists(candidates[0], function(exists) {
                                if (exists) {
                                    return dispatch["static"]("/" + path_tools.basename(candidates[0]), req, res);
                                } else {
                                    return send_static_home(candidates.slice(1));
                                }
                            });
                        }
                    };

                    send_static_home(homes);
                }

                if (pathname !== "/") {
                    if (dispatch.serve_static) {
                        return dispatch["static"](pathname, req, res);
                    } else {
                        return dispatch._404(req, res, pathname);
                    }
                }
            };

            if (dispatch.use_nsr_session) {
                nsr_sid = dispatch.getCookie(req, "nsr_sid")["nsr_sid"];

                if (!nsr_sid) {
                    nsr_sid = uuid();

                    dispatch.setCookie(res, {
                        nsr_sid: nsr_sid
                    });
                }

                dispatch.getSession(req);
            }

            return final_dispatch(req, res);
        };

        _extend(default_options, options);
