function requestListener(req, res) {
    if (argv.cors) {
        res.setHeader("Access-Control-Allow-Origin", "*");
        res.setHeader("Access-Control-Request-Method", "*");
        res.setHeader("Access-Control-Allow-Methods", "OPTIONS, GET");
        res.setHeader("Access-Control-Allow-Headers", "authorization, content-type");

        if (req.method === "OPTIONS") {
            res.writeHead(200);
            res.end();
            return;
        }
    }

    const url = req.url.split("?")[0];
    const possibleFilename = resolveUrl(url.slice(1)) || "dummy";

    fs.stat(possibleFilename, function(err, stats) {
        let fileBuffer;

        if (!err && stats.isFile()) {
            fileBuffer = fs.readFileSync(possibleFilename);
            const ct = mime.lookup(possibleFilename);
            log(`Sending ${possibleFilename} with Content-Type ${ct}`);

            res.writeHead(200, {
                "Content-Type": ct
            });
        } else {
            log("Route %s, replacing with index.html", possibleFilename);
            fileBuffer = returnDistFile();

            res.writeHead(200, {
                "Content-Type": "text/html"
            });
        }

        res.write(fileBuffer);
        res.end();
    });
}

