async function certificateFor<O extends Options>(domain: string, options: O = {} as O): Promise<IReturnData<O>> {
    debug(
        `Certificate requested for ${domain}. Skipping certutil install: ${Boolean(options.skipCertutilInstall)}. Skipping hosts file: ${Boolean(options.skipHostsFile)}`
    );

    if (options.ui) {
        Object.assign(UI, options.ui);
    }

    if (!isMac && !isLinux && !isWindows) {
        throw new Error(`Platform not supported: "${process.platform}"`);
    }

    if (!commandExists("openssl")) {
        throw new Error(
            "OpenSSL not found: OpenSSL is required to generate SSL certificates - make sure it is installed and available in your PATH"
        );
    }

    const domainKeyPath = pathForDomain(domain, `private-key.key`);
    const domainCertPath = pathForDomain(domain, `certificate.crt`);

    if (!exists(rootCAKeyPath)) {
        debug(
            "Root CA is not installed yet, so it must be our first run. Installing root CA ..."
        );

        await installCertificateAuthority(options);
    } else if (options.getCaBuffer || options.getCaPath) {
        debug(
            "Root CA is not readable, but it probably is because an earlier version of devcert locked it. Trying to fix..."
        );

        await ensureCACertReadable(options);
    }

    if (!exists(pathForDomain(domain, `certificate.crt`))) {
        debug(
            `Can't find certificate file for ${domain}, so it must be the first request for ${domain}. Generating and caching ...`
        );

        await generateDomainCertificate(domain);
    }

    if (!options.skipHostsFile) {
        await currentPlatform.addDomainToHostFileIfMissing(domain);
    }

    debug(`Returning domain certificate`);

    const ret = {
        key: readFile(domainKeyPath),
        cert: readFile(domainCertPath)
    } as IReturnData<O>;

    if (options.getCaBuffer)
        (ret as ICaBuffer).ca = readFile(rootCACertPath);

    if (options.getCaPath)
        (ret as ICaPath).caPath = rootCACertPath;

    return ret;
}

