                                }
                            });

                            if (processesString !== "*") {
                                const processesMissing = processes.filter(function(name) {
                                    return (procStats.filter(function(item) {
                                        return item.name.toLowerCase().indexOf(name) >= 0;
                                    }).length === 0);
                                });

                                processesMissing.forEach(function(procName) {
                                    result.push({
                                        proc: procName,
                                        pid: null,
                                        pids: [],
