                                });

                                let cmd = "cat /proc/stat | grep \"cpu \"";

                                for (const i in result) {
                                    for (const j in result[i].pids) {
                                        cmd += ";cat /proc/" + result[i].pids[j] + "/stat";
                                    }
                                }

                                exec(cmd, {
                                    maxBuffer: 1024 * 20000
