                                        callback(result);
                                    }

                                    resolve(result);
                                });
                            } else {
                                if (callback) {
                                    callback(result);
                                }

                                resolve(result);
                            }
                        } else {
                            if (callback) {
                                callback(result);
                            }

                            resolve(result);
                        }
                    });
                }
            }
        });
    });
