function plot(options: PlotOptions): Promise<boolean> | void {
    if (options.finish) {
        return plotCallack(options);
    }

    return new Promise((resolve, reject) => {
        plotCallack({
            ...options,

            finish: error => {
                if (error) {
                    return reject(error);
                }

                resolve(true);
            }
        });
    });
}

function plot(options: PlotOptions): Promise<boolean> | void {
    const f = validFilename.path(options.filename);

    if (f !== options.filename) {
        throw new Error(`invalid filename of '${options.filename}' -- ${f}`);
    }

    if (options.finish) {
        return plotCallack(options);
    }

    return new Promise((resolve, reject) => {
        plotCallack({
            ...options,

            finish: error => {
                if (error) {
                    return reject(error);
                }

                resolve(true);
            }
        });
    });
}

function attachedPublicKey(
    contactDetailsModel,
    keyCache,
    keysModel,
    autoPinPrimaryKeys,
    sendPreferences,
    publicKeyStore,
    AttachmentLoader,
    contactEmails,
    Contact,
    networkActivityTracker
) {
    const extractAddress = email => {
        const [name = "", adr = ""] = email.replace(CLOSE_TAG_AUTOCOMPLETE_RAW, "").split(OPEN_TAG_AUTOCOMPLETE_RAW);

        return {
            name: name.trim(),
            adr: adr.trim()
        };
    };

    const populateAddresses = (keyInfo, addresses) => {
        const sendInfo = sendPreferences.get(_.map(addresses, "adr"));
        const trustedKeys = publicKeyStore.get(_.map(addresses, "adr"));

        return Promise.all([sendInfo, trustedKeys]).then(([sendPref, publicKeys]) => addresses.filter((
            {
                adr
            }
        ) => publicKeys[adr].every((
            {
                key
            }
        ) => getFingerprint(key) !== keyInfo.fingerprint)).map(address => {
            if (keyInfo.expires !== null && keyInfo.expires < Date.now()) {
                return _.extend({}, address, {
                    encrypt: false,
                    expired: true
                });
            }

            if (sendPref[address.adr].scheme === SEND_TYPES.SEND_PM) {
                return _.extend({}, address, {
                    encrypt: false
                });
            }

            if (sendPref[address.adr].publickeys.length === 0) {
                return _.extend({}, address, {
                    encrypt: true
                });
            }

            if (sendPref[address.adr].publickeys[0].getCreationTime() > keyInfo.created) {
                return _.extend({}, address, {
                    encrypt: false
                });
            }

            return _.extend({}, address, {
                encrypt: sendPref[address.adr].encrypt
            });
        }));
    };

    const senderAddress = (
        {
            Sender: {
                Address,
                Name
            }
        }
    ) => {
        return {
            name: Name,
            adr: Address
        };
    };

    const extractAddresses = (message, keyInfo) => {
        const userids = keyInfo.userIds.map(extractAddress).filter((
            {
                adr
            }
        ) => adr);

        if (!userids.length) {
            return populateAddresses(keyInfo, [senderAddress(message)]);
        }

        return populateAddresses(keyInfo, userids);
    };

    const getPublicKeyFromSig = async message => {
        const privateKeys = keysModel.getPrivateKeys(message.AddressID);

        const {
            [message.SenderAddress]: {
                Keys: keys
            }
        } = await keyCache.get([message.SenderAddress]);

        const publicKeys = (await addGetKeys(keys, "PublicKey")).reduce((
            acc,
            {
                Flags,
                keys
            }
        ) => {
            if (Flags & KEY_FLAGS.ENABLE_VERIFICATION) {
                acc.push(keys[0]);
            }

            return acc;
        }, []);

        if (publicKeys.length === 0) {
            return false;
        }

        const {
            signatures: [signature = false]
        } = await decryptMessageLegacy({
            message: message.Body,
            messageDate: getDate(message),
            privateKeys,
            publicKeys
        });

        if (!signature) {
            return false;
        }

        const publicKey = await getMatchingKey(signature, publicKeys);
        return publicKey.armor();
    };

    const extractPublicKeysFromAutocrypt = message => {
        if (!_.has(message.ParsedHeaders, "Autocrypt")) {
            return [];
        }

        const autocrypt = toList(message.ParsedHeaders.Autocrypt);

        return _.filter(autocrypt.map(header => {
            const match = header.match(
                /^(\s*(_[^;\s]*|addr|prefer-encrypt)\s*=\s*[^;\s]*\s*;)*\s*keydata\s*=([^;]*)$/
            );

            if (!match) {
                return null;
            }

            const preferEncryptMutual = header.match(
                /^(\s*(_[^;\s]*|addr)\s*=\s*[^;\s]*\s*;)*\s*prefer-encrypt\s*=\s*mutual\s*;/
            );

            if (!preferEncryptMutual) {
                return null;
            }

            const keydata = header.match(/^(?:\s*(?:[^;\s]*)\s*=\s*[^;\s]*\s*;)*\s*keydata\s*=([^;]*)$/);

            try {
                return binaryStringToArray(decodeBase64(keydata[1]));
            } catch (e) {
                return null;
            }
        }));
    };

    const keySignsMessage = async (message, keyInfos) => {
        const privateKeys = keysModel.getPrivateKeys(message.AddressID);

        try {
            const {
                signatures
            } = await decryptMessageLegacy({
                message: message.Body,
                messageDate: getDate(message),
                privateKeys
            });

            const signaturePackets = _.flatten(signatures.map((
                {
                    packets
                }
            ) => Object.values(packets).filter(a => typeof a === "object")));

            const signingKeyIds = signaturePackets.map((
                {
                    issuerKeyId: {
                        bytes
                    }
                }
            ) => bytes);

            return (await addGetKeys(keyInfos, "publicKeyArmored")).filter((
                {
                    keys: keyList
                }
            ) => {
                const keyIds = _.flatten(keyList.map(key => key.getKeyIds().map((
                    {
                        bytes
                    }
                ) => bytes)));

