public async run(
    {
        inputDir,
        outputDir,
        parsedLocationAnnotation,
        etag
    }: GeneratorRunOptions
): Promise<void> {
    const [log, logStream] = createStream();

    if (parsedLocationAnnotation) {
        await patchMkdocsYmlPreBuild(path.join(inputDir, "mkdocs.yml"), this.logger, parsedLocationAnnotation);
    }

    const mountDirs = {
        [inputDir]: "/input",
        [outputDir]: "/output"
    };

    try {
        switch (this.options.runGeneratorIn) {
        case "local":
            await runCommand({
                command: "mkdocs",
                args: ["build", "-d", outputDir, "-v"],

                options: {
                    cwd: inputDir
                },

                logStream
            });

            this.logger.info(
                `Successfully generated docs from ${inputDir} into ${outputDir} using local mkdocs`
            );

            break;
        case "docker":
            await this.containerRunner.runContainer({
                imageName: "spotify/techdocs",
                args: ["build", "-d", "/output"],
                logStream,
                mountDirs,
                workingDir: "/input",

                envVars: {
                    HOME: "/tmp"
                }
            });

            this.logger.info(
                `Successfully generated docs from ${inputDir} into ${outputDir} using techdocs-container`
            );

            break;
        default:
            throw new Error(
                `Invalid config value "${this.options.runGeneratorIn}" provided in 'techdocs.generators.techdocs'.`
            );
        }
    } catch (error) {
        this.logger.debug(`Failed to generate docs from ${inputDir} into ${outputDir}`);
        this.logger.error(`Build failed with error: ${log}`);

        throw new Error(
            `Failed to generate docs from ${inputDir} into ${outputDir} with error ${error.message}`
        );
    }

    await addBuildTimestampMetadata(path.join(outputDir, "techdocs_metadata.json"), this.logger);

    if (etag) {
        await storeEtagMetadata(path.join(outputDir, "techdocs_metadata.json"), etag);
    }
}

