function nestie(input, glue) {
    glue = glue || ".";
    let arr;
    let tmp;
    let output;
    let i = 0;
    let k;
    let key;

    for (k in input) {
        tmp = output;
        arr = k.split(glue);

        for (i = 0; i < arr.length; ) {
            key = arr[i++];

            if (tmp == null) {
                tmp = empty("" + key);
                output = output || tmp;
            }

            if (key == "__proto__") {
                break;
            }

            if (i < arr.length) {
                if (key in tmp) {
                    tmp = tmp[key];
                } else {
                    tmp = tmp[key] = empty("" + arr[i]);
                }
            } else {
                tmp[key] = input[k];
            }
        }
    }

    return output;
}

