            res.end(STATUS_CODES[400]);
            return;
        }

        const parsedUrl = url.parse(req.url);
        let pathname = path.join(publicDir, (parsedUrl.pathname || ".").replace(/^(\.)+/, "."));

        fs.stat(pathname, (statErr, stat) => {
