        const socket = socketsById[socketId];

        if (!socket) {
            res.status(400).json({
                error: `No such socket: ${socketId}`,
                errorCode: "invalid-socket-id"
            });
        } else {
            next();
        }
    };

    const emitWorkingTreeChanged = _.debounce(repoPath => {
        if (io && repoPath) {
            io.in(path.normalize(repoPath)).emit("working-tree-changed", {
                repository: repoPath
            });

            logger.info("emitting working-tree-changed to sockets, manually triggered");
        }
    }, 500, {
        maxWait: 1000
    });

    const emitGitDirectoryChanged = _.debounce(repoPath => {
        if (io && repoPath) {
