            const task = gitPromise(["submodule", "deinit", "-f", req.query.submoduleName], req.query.path).then(
                gitPromise.bind(null, ["rm", "-f", req.query.submoduleName], req.query.path)
            ).then(() => {
                rimraf.sync(path.join(req.query.path, req.query.submodulePath));
                rimraf.sync(path.join(req.query.path, ".git", "modules", req.query.submodulePath));
            });

            jsonResultOrFailProm(res, task);
        }
    );

    app.get(`${exports.pathPrefix}/quickstatus`, ensureAuthenticated, (req, res) => {
        const task = fs.access(req.query.path).then(() => {
            return gitPromise.revParse(req.query.path);
        }).then(revParseRes => {
            if (revParseRes.type !== "uninited") {
                return revParseRes;
            }

            return fs.readdir(req.query.path).then(filePaths => {
                return Promise.all(
                    filePaths.filter(filePath => !filePath.startsWith(".")).map(filePath => gitPromise.revParse(path.join(req.query.path, filePath)))
                );
            }).then(pathRevParses => {
                revParseRes.subRepos = pathRevParses.filter(
                    pathRevParse => pathRevParse.type === "inited" || pathRevParse.type === "bare"
                ).map(pathRevParse => pathRevParse.gitRootPath);

                return revParseRes;
            });
        }).catch(e => {
            logger.error("failed during /quickstatus", e);

            return {
                type: "no-such-path",
                gitRootPath: req.query.path
            };
        });

        jsonResultOrFailProm(res, task);
    });

    app.get(
        `${exports.pathPrefix}/stashes`,
        ensureAuthenticated,
        ensurePathExists,
        (req, res) => {
            const task = gitPromise([
                "stash",
                "list",
                "--decorate=full",
                "--pretty=fuller",
                "-z",
                "--parents",
                "--numstat"
            ], req.query.path).then(gitParser.parseGitLog);

            jsonResultOrFailProm(res, task);
        }
    );

    app.post(
        `${exports.pathPrefix}/stashes`,
        ensureAuthenticated,
        ensurePathExists,
        (req, res) => {
            jsonResultOrFailProm(res, gitPromise(
                ["stash", "save", "--include-untracked", req.body.message || ""],
                req.body.path
            )).finally(emitGitDirectoryChanged.bind(null, req.body.path)).finally(emitWorkingTreeChanged.bind(null, req.body.path));
        }
    );

    app.delete(
        `${exports.pathPrefix}/stashes/:id`,
        ensureAuthenticated,
        ensurePathExists,
        (req, res) => {
            const type = req.query.apply === "true" ? "apply" : "drop";

            jsonResultOrFailProm(
                res,
                gitPromise(["stash", type, `stash@{${req.params.id}}`], req.query.path)
            ).finally(emitGitDirectoryChanged.bind(null, req.query.path)).finally(emitWorkingTreeChanged.bind(null, req.query.path));
        }
    );

    app.get(`${exports.pathPrefix}/gitconfig`, ensureAuthenticated, (req, res) => {
        jsonResultOrFailProm(res, gitPromise(["config", "--list"]).then(gitParser.parseGitConfig));
    });

    app.get(`${exports.pathPrefix}/credentials`, (req, res) => {
        if (req.ip != "127.0.0.1" && req.ip != "::ffff:127.0.0.1") {
            logger.info(`Trying to get credentials from unathorized ip: ${req.ip}`);

            res.status(400).json({
                errorCode: "request-from-unathorized-location"
            });

            return;
        }

        const socket = socketsById[req.query.socketId];
        const remote = req.query.remote;

        if (!socket) {
            logger.info(`Trying to get credentials from unavailable socket: ${req.query.socketId}`);

            res.status(400).json({
                errorCode: "socket-unavailable"
            });
        } else {
            socket.once("credentials", data => res.json(data));

            socket.emit("request-credentials", {
                remote: remote
            });
        }
    });

    app.post(`${exports.pathPrefix}/createdir`, ensureAuthenticated, (req, res) => {
        const dir = req.query.dir || req.body.dir;

        if (!dir) {
            return res.status(400).json({
                errorCode: "missing-request-parameter",
                error: "You need to supply the path request parameter"
            });
        }

        mkdirp(dir).then(() => res.json({})).catch(err => res.status(400).json(err));
    });

    app.get(
        `${exports.pathPrefix}/gitignore`,
        ensureAuthenticated,
        ensurePathExists,
        (req, res) => {
            fs.readFile(path.join(req.query.path, ".gitignore")).then(ignoreContent => res.status(200).json({
                content: ignoreContent.toString()
            })).catch(e => {
                if (e && e.message && e.message.indexOf("no such file or directory") > -1) {
                    res.status(200).json({
                        content: ""
                    });
                } else {
                    res.status(500).json(e);
                }
            });
        }
    );

    app.put(
        `${exports.pathPrefix}/gitignore`,
        ensureAuthenticated,
        ensurePathExists,
        (req, res) => {
            if (!req.body.data && req.body.data !== "") {
                return res.status(400).json({
                    message: "Invalid .gitignore content"
                });
            }

            fs.writeFile(path.join(req.body.path, ".gitignore"), req.body.data).then(() => res.status(200).json({})).finally(emitGitDirectoryChanged.bind(null, req.body.path)).catch(e => res.status(500).json(e));
        }
    );

    if (config.dev) {
        app.post(
            `${exports.pathPrefix}/testing/createtempdir`,
            ensureAuthenticated,
            (req, res) => {
                temp.mkdir("test-temp-dir", (err, tempPath) => res.json({
                    path: path.normalize(tempPath)
                }));
            }
        );

        app.post(
            `${exports.pathPrefix}/testing/createfile`,
            ensureAuthenticated,
            (req, res) => {
                const content = req.body.content ? req.body.content : `test content\n${Math.random()}\n`;
                fs.writeFile(req.body.file, content).then(() => res.json({})).then(emitWorkingTreeChanged.bind(null, req.body.path));
            }
        );

        app.post(
            `${exports.pathPrefix}/testing/changefile`,
            ensureAuthenticated,
            (req, res) => {
                const content = req.body.content ? req.body.content : `test content\n${Math.random()}\n`;
                fs.writeFile(req.body.file, content).then(() => res.json({})).then(emitWorkingTreeChanged.bind(null, req.body.path));
            }
        );

        app.post(
            `${exports.pathPrefix}/testing/createimagefile`,
            ensureAuthenticated,
            (req, res) => {
                fs.writeFile(req.body.file, "png", {
                    encoding: "binary"
                }).then(() => res.json({})).then(emitWorkingTreeChanged.bind(null, req.body.path));
            }
        );

        app.post(
            `${exports.pathPrefix}/testing/changeimagefile`,
            ensureAuthenticated,
            (req, res) => {
                fs.writeFile(req.body.file, "png ~~", {
                    encoding: "binary"
                }).then(() => res.json({})).then(emitWorkingTreeChanged.bind(null, req.body.path));
            }
        );

        app.post(
            `${exports.pathPrefix}/testing/removefile`,
            ensureAuthenticated,
            (req, res) => {
                fs.unlink(req.body.file).then(() => res.json({})).then(emitWorkingTreeChanged.bind(null, req.body.path));
            }
        );

        app.post(`${exports.pathPrefix}/testing/git`, ensureAuthenticated, (req, res) => {
            jsonResultOrFailProm(res, gitPromise(req.body.command, req.body.path)).then(emitWorkingTreeChanged.bind(null, req.body.path));
        });

        app.post(`${exports.pathPrefix}/testing/cleanup`, (req, res) => {
            temp.cleanup((err, cleaned) => {
                logger.info("Cleaned up: " + JSON.stringify(cleaned));

                res.json({
                    result: cleaned
                });
            });
        });
    }
}

function escapeShellArgWithInterpolation(arg, shell) {
    let result = arg.replace(/\u{0}/gu, "").replace(/\\/g, "\\\\").replace(/^(~|#)/g, "\\$1").replace(/(\*|\?)/gu, "\\$1").replace(/(\$|\;|\&|\|)/g, "\\$1").replace(/(\(|\)|\<|\>)/g, "\\$1").replace(/("|'|`)/g, "\\$1");

    if (shell.endsWith("zsh")) {
        result = result.replace(/^=/gu, "\\=").replace(/(\[|\]|\{|\})/g, "\\$1");
    }

    return result;
}

function escapeShellArgWithInterpolation(arg, shell) {
    let result = arg.replace(/\u{0}/gu, "").replace(/\\/g, "\\\\").replace(/^(~|#)/g, "\\$1").replace(/(\*|\?)/gu, "\\$1").replace(/(\$|\;|\&|\|)/g, "\\$1").replace(/(\(|\)|\<|\>)/g, "\\$1").replace(/("|'|`)/g, "\\$1");

    if (shell.endsWith("zsh")) {
        result = result.replace(/^=/gu, "\\=").replace(/(\[|\]|\{|\})/g, "\\$1");
    } else {
        result = result.replace(/(?<=\=(?:.*?:)?)(~)(?=\:|$)/g, "\\$1");
    }

    return result;
}

function getLockfile(
    packageFile,
    date,
    {
        npmNeeded,
        only,
        logger = () => {}
    } = {}
) {
    if (typeof packageFile !== "string" || packageFile.length === 0) {
        return Promise.reject(
            colors.red(`\`packageFile\` must be a non-empty string; got ${inspect(packageFile)}`)
        );
    }

    if (typeof date !== "undefined" && !new Date(date).getTime()) {
        return Promise.reject(
            colors.red(`\`date\` must be a valid Date format if provided; got ${inspect(date)}`)
        );
    }

    const tmpDirP = getProjectTempDir({
        npmNeeded,
        logger
    });

    const npmRC = path.join(path.dirname(packageFile), ".npmrc");

    const copyPkg = tmpDirP.then(tmpDir => {
        logger(
            colors.blue(`Creating \`package.json\` in temp dir for ${date || "“now”"} lockfile`)
        );

        return Promise.all([
            copyFile(packageFile, path.join(tmpDir, "package.json")),
            copyFile(npmRC, path.join(tmpDir, ".npmrc")).catch(err => {
                if (!err || !/^ENOENT: no such file or directory/.test(err.message)) {
                    throw err;
                }
            })
        ]);
    });

    return Promise.all([tmpDirP, copyPkg]).then(([tmpDir]) => new Promise((resolve, reject) => {
        const PATH = path.join(tmpDir, "../node_modules/.bin");

        logger(
            colors.blue(`Running npm install to create lockfile for ${date || "“now”"}...`)
        );

        exec(
            `npm install --ignore-scripts --package-lock --package-lock-only${date ? ` --before=${date}` : ""}${only ? ` --only=${only}` : ""}`,
            {
                cwd: tmpDir,

                env: {
                    PATH: `${PATH}:${process.env.PATH}`,
                    NODE_ENV: process.env.NODE_ENV
                }
            },
            err => {
                if (err) {
                    reject(err);
                } else {
                    resolve(tmpDir);
                }
            }
        );
    })).then(tmpDir => {
        logger(colors.blue(`Reading lockfile contents for ${date || "“now”"}...`));
        const lockfile = path.join(tmpDir, "package-lock.json");

        return readFile(lockfile, {
            encoding: "utf-8"
        });
    });
}

