async (url: URL, cacheInfo: CacheInfo, options?: SourceOptions): Promise<string> => {
    let branch = cacheInfo.branch;

    const {
        path: repo,
        origin,
        repoName
    } = cacheInfo;

    if (options?.cache && existsSync(repo)) {
        logger.info(`will copy repo ${logger.grn(repoName)} (cached)`);
        return repo;
    }

    logger.debug({
        url,
        branch,
        repo,
        origin
    });

    logger.info(
        `will clone ${branch ? `${logger.blu(branch)} of ` : ""}${logger.ylw(origin)} into ${logger.grn(repoName)}`
    );

    const cwd = repo;

    try {
        await promises.mkdir(repo, {
            recursive: true
        });

        if (!existsSync(join(cwd, ".git"))) {
            await exec("git init", {
                cwd
            });

            await exec(`git remote add -f origin ${origin}`, {
                cwd
            });
        }

        if (options?.subdirs?.length) {
            await exec("git config core.sparseCheckout true", {
                cwd
            });

            await promises.writeFile(join(cwd, ".git/info/sparse-checkout"), options?.subdirs.join("\n"), {
                encoding: "utf8"
            });
        }

        if (!branch) {
            let res = await exec("git symbolic-ref refs/remotes/origin/HEAD", {
                cwd
            }).catch(() => ({
                stdout: ""
            }));

            if (!res?.stdout) {
                await exec("git remote set-head origin --auto", {
                    cwd
                });

                res = await exec("git symbolic-ref refs/remotes/origin/HEAD", {
                    cwd
                });
            }

            branch = basename(res?.stdout?.replace?.(/\n/g, ""));
        }

        await exec(`git pull origin ${branch}`, {
            cwd
        });

        return repo;
    } catch (e) {
        await promises.rmdir(repo, {
            recursive: true,
            force: true
        } as any).catch(() => null);

        throw e;
    }
}

