function fetchTask(remote: string, branch: string, customArgs: string[]): StringTask<FetchResult> {
    const commands = ["fetch", ...customArgs];

    if (remote && branch) {
        commands.push(remote, branch);
    }

    return {
        commands,
        format: "utf-8",
        parser: parseFetchResult
    };
}

function fetchTask(remote: string, branch: string, customArgs: string[]): StringTask<FetchResult> | EmptyTask {
    const commands = ["fetch", ...customArgs];

    if (remote && branch) {
        commands.push(remote, branch);
    }

    const banned = commands.find(disallowedCommand);

    if (banned) {
        return configurationErrorTask(`git.fetch: potential exploit argument blocked.`);
    }

    return {
        commands,
        format: "utf-8",
        parser: parseFetchResult
    };
}

function renderConnection(connection, user) {
    const replaced = {};

    Object.keys(connection).forEach(key => {
        if (key === "data") {
            const value = renderConnection(connection.data, user);
            connection.data = value;
        } else {
            const value = connection[key];

            if (typeof value === "string") {
                _.templateSettings.interpolate = /{{([\s\S]+?)}}/g;
                const compiled = _.template(value);

                replaced[key] = compiled({
                    user
                });
            } else {
                replaced[key] = value;
            }
        }
    });

    return replaced;
}

