(function() {
    function parseURL(text) {
        const xml = new window.DOMParser().parseFromString(text, "text/xml");
        const tag = xml.getElementsByTagName("Key")[0];
        return decodeURI(tag.childNodes[0].nodeValue);
    }

    function waitForAllFiles(form) {
        if (window.uploading !== 0) {
            setTimeout(function() {
                waitForAllFiles(form);
            }, 100);
        } else {
            window.HTMLFormElement.prototype.submit.call(form);
        }
    }

    function request(method, url, data, fileInput, file, form) {
        file.loaded = 0;

        return new Promise(function(resolve, reject) {
            const xhr = new window.XMLHttpRequest();

            xhr.onload = function() {
                if (xhr.status === 201) {
                    resolve(xhr.responseText);
                } else {
                    reject(xhr.statusText);
                }
            };

            xhr.upload.onprogress = function(e) {
                const diff = e.loaded - file.loaded;
                form.loaded += diff;
                fileInput.loaded += diff;
                file.loaded = e.loaded;

                const defaultEventData = {
                    currentFile: file,
                    currentFileName: file.name,
                    currentFileProgress: Math.min(e.loaded / e.total, 1),
                    originalEvent: e
                };

                form.dispatchEvent(new window.CustomEvent("progress", {
                    detail: Object.assign({
                        progress: Math.min(form.loaded / form.total, 1),
                        loaded: form.loaded,
                        total: form.total
                    }, defaultEventData)
                }));

                fileInput.dispatchEvent(new window.CustomEvent("progress", {
                    detail: Object.assign({
                        progress: Math.min(fileInput.loaded / fileInput.total, 1),
                        loaded: fileInput.loaded,
                        total: fileInput.total
                    }, defaultEventData)
                }));
            };

            xhr.onerror = function() {
                reject(xhr.statusText);
            };

            xhr.open(method, url);
            xhr.send(data);
        });
    }

    function uploadFiles(form, fileInput, name) {
        const url = fileInput.getAttribute("data-url");
        fileInput.loaded = 0;
        fileInput.total = 0;

        const promises = Array.from(fileInput.files).map(function(file) {
            form.total += file.size;
            fileInput.total += file.size;
            const s3Form = new window.FormData();

            Array.from(fileInput.attributes).forEach(function(attr) {
                let name = attr.name;

                if (name.startsWith("data-fields")) {
                    name = name.replace("data-fields-", "");
                    s3Form.append(name, attr.value);
                }
            });

            s3Form.append("success_action_status", "201");
            s3Form.append("Content-Type", file.type);
            s3Form.append("file", file);
            return request("POST", url, s3Form, fileInput, file, form);
        });

        Promise.all(promises).then(function(results) {
            results.forEach(function(result) {
                const hiddenFileInput = document.createElement("input");
                hiddenFileInput.type = "hidden";
                hiddenFileInput.name = name;
                hiddenFileInput.value = parseURL(result);
                form.appendChild(hiddenFileInput);
            });

            fileInput.name = "";
            window.uploading -= 1;
        }, function(err) {
            console.log(err);
            fileInput.setCustomValidity(err);
            fileInput.reportValidity();
        });
    }

    function clickSubmit(e) {
        const submitButton = e.target;
        const form = submitButton.closest("form");
        const submitInput = document.createElement("input");
        submitInput.type = "hidden";
        submitInput.value = submitButton.value || "1";
        submitInput.name = submitButton.name;
        form.appendChild(submitInput);
    }

    function uploadS3Inputs(form) {
        window.uploading = 0;
        form.loaded = 0;
        form.total = 0;
        const inputs = Array.from(form.querySelectorAll(".s3file"));

        inputs.forEach(function(input) {
            const hiddenS3Input = document.createElement("input");
            hiddenS3Input.type = "hidden";
            hiddenS3Input.name = "s3file";
            hiddenS3Input.value = input.name;
            form.appendChild(hiddenS3Input);
        });

        inputs.forEach(function(input) {
            window.uploading += 1;
            uploadFiles(form, input, input.name);
        });

        waitForAllFiles(form);
    }

    document.addEventListener("DOMContentLoaded", function() {
        let forms = Array.from(document.querySelectorAll(".s3file")).map(function(input) {
            return input.closest("form");
        });

        forms = new Set(forms);

        forms.forEach(function(form) {
            form.addEventListener("submit", function(e) {
                e.preventDefault();
                uploadS3Inputs(e.target);
            });

            const submitButtons = form.querySelectorAll("input[type=submit], button[type=submit]");

            Array.from(submitButtons).forEach(function(submitButton) {
                submitButton.addEventListener("click", clickSubmit);
            });
        });
    });
})

async [_convert](input, options) {
    input = Buffer.isBuffer(input) ? input.toString("utf8") : input;

    const {
        provider
    } = this;

    const svg = cheerio.default.html(this[_sanitize](cheerio.load(input, null, false)("svg"), options));

    if (!svg) {
        throw new Error("SVG element not found in input. Check the SVG input");
    }

    const html = `<!DOCTYPE html>
<html>
<head>
<base href="${options.baseUrl}">
<meta charset="utf-8">
<style>
* { margin: 0; padding: 0; }
html { background-color: ${provider.getBackgroundColor(options)}; }
</style>
</head>
<body>${svg}</body>
</html>`;

    const page = await this[_getPage](html);
    await this[_setDimensions](page, options);
    const dimensions = await this[_getDimensions](page, options);

    if (options.scale !== 1) {
        dimensions.height *= options.scale;
        dimensions.width *= options.scale;
        await this[_setDimensions](page, dimensions);
    }

    await page.setViewport(dimensions);

    return await page.screenshot(Object.assign({
        type: provider.getType(),

        clip: Object.assign({
            x: 0,
            y: 0
        }, dimensions)
    }, provider.getScreenshotOptions(options)));
}

