(
    {
        chart,
        config
    }: MermaidProps
): ReactElement<MermaidProps> => {
    if (typeof window === "undefined") {
        return <div></div>;
    }

    const html: HTMLHtmlElement = document.querySelector("html")!;
    const [theme, setTheme] = useState<mermaidAPI.Theme>(getTheme(html, config));

    useEffect(() => {
        const observer = new MutationObserver(mutations => {
            for (const mutation of mutations) {
                if (mutation.type !== "attributes" || mutation.attributeName !== "data-theme") {
                    continue;
                }

                setTheme(getTheme(mutation.target as HTMLHtmlElement, config));
                break;
            }
        });

        observer.observe(html, {
            attributes: true
        });

        return () => {
            try {
                observer.disconnect();
            } catch {}
        };
    }, [chart, config, theme]);

    const [svg, setSvg] = useState<string>("");

    useEffect(() => {
        const render = () => {
            mermaid.render(`mermaid-svg-${id.toString()}`, chart, renderedSvg => setSvg(renderedSvg));
            id++;
        };

        if (config) {
            if (config.mermaid) {
                mermaid.initialize({
                    startOnLoad: true,
                    ...config.mermaid,
                    theme
                });
            } else {
                mermaid.initialize({
                    startOnLoad: true,
                    theme
                });
            }

            render();
        } else {
            setTimeout(render, 0);
        }
    }, [theme, chart]);

    return (
        <div
            dangerouslySetInnerHTML={{
                __html: svg
            }}></div>
    );
}

