                setRerender(cur => !cur);
                break;
            }
        });

        observer.observe(html, {
            attributes: true
        });

        return () => {
            try {
                observer.disconnect();
            } catch {}
        };
    }, []);

    useEffect(() => {
        if (config) {
            if (config.mermaid) {
                mermaid.initialize({
