            const $lastTr = $(this._lastChecked);
            let lastIndex = $lastTr.index();
            let currentIndex = $tr.index();
            const $rows = this.$fileList.children("tr");

            if (lastIndex > currentIndex) {
                const aux = lastIndex;
                lastIndex = currentIndex;
                currentIndex = aux;
            }

            for (let i = lastIndex; i <= currentIndex; i++) {
                this._selectFileEl($rows.eq(i), !checked);
            }

            this._removeHalfSelection();
            this._selectionMode = "single";
        },

        _selectSingle: function($tr) {
            const state = !$tr.hasClass("selected");
            this._selectFileEl($tr, state);
        },

        _onMouseOverCheckbox: function(e) {
            if (this._getCurrentSelectionMode() !== "range") {
                return;
            }

            const $currentTr = $(e.target).closest("tr");
            const $lastTr = $(this._lastChecked);
            let lastIndex = $lastTr.index();
            let currentIndex = $currentTr.index();
            const $rows = this.$fileList.children("tr");

            if (lastIndex > currentIndex) {
                const aux = lastIndex;
                lastIndex = currentIndex;
                currentIndex = aux;
            }

            this._removeHalfSelection();

            for (let i = 0; i <= $rows.length; i++) {
                const $tr = $rows.eq(i);
                const $checkbox = $tr.find("td.selection>.selectCheckBox");

                if (lastIndex <= i && i <= currentIndex) {
                    $tr.addClass("halfselected");
                    $checkbox.prop("checked", true);
                }
            }
        },

        _removeHalfSelection: function() {
            const $rows = this.$fileList.children("tr");

            for (let i = 0; i <= $rows.length; i++) {
                const $tr = $rows.eq(i);
                $tr.removeClass("halfselected");
                const $checkbox = $tr.find("td.selection>.selectCheckBox");
                $checkbox.prop("checked", !!this._selectedFiles[$tr.data("id")]);
            }
        },

        _onClickFile: function(event) {
            const $tr = $(event.target).closest("tr");

            if ($tr.hasClass("dragging")) {
                return;
            }

            if (this._allowSelection && event.shiftKey) {
                event.preventDefault();
                this._selectRange($tr);
                this._lastChecked = $tr;
                this.updateSelectionSummary();
            } else if (!event.ctrlKey) {
                if (!this._detailsView || $(event.target).is(".nametext, .name, .thumbnail") || $(event.target).closest(".nametext").length) {
                    var filename = $tr.attr("data-file");
                    const renaming = $tr.data("renaming");

                    if (this._defaultFileActionsDisabled) {
                        event.preventDefault();
                    } else if (!renaming) {
                        this.fileActions.currentFile = $tr.find("td");
                        const spec = this.fileActions.getCurrentDefaultFileAction();

                        if (spec && spec.action) {
                            event.preventDefault();

                            spec.action(filename, {
                                $file: $tr,
                                fileList: this,
                                fileActions: this.fileActions,
                                dir: $tr.attr("data-path") || this.getCurrentDirectory()
                            });
                        }

                        $(event.target).closest("a").blur();
                    }
                } else {
                    event.preventDefault();
                    var filename = $tr.attr("data-file");
                    this.fileActions.currentFile = $tr.find("td");
                    const mime = this.fileActions.getCurrentMimeType();
                    const type = this.fileActions.getCurrentType();
                    const permissions = this.fileActions.getCurrentPermissions();
                    const action = this.fileActions.get(mime, type, permissions, filename)["Details"];

                    if (action) {
                        action(filename, {
                            $file: $tr,
                            fileList: this,
                            fileActions: this.fileActions,
                            dir: $tr.attr("data-path") || this.getCurrentDirectory()
                        });
                    }
                }
            }
        },

        _onClickFileCheckbox: function(e) {
            const $tr = $(e.target).closest("tr");

            if (this._getCurrentSelectionMode() === "range") {
                this._selectRange($tr);
            } else {
                this._selectSingle($tr);
            }

            this._lastChecked = $tr;
            this.updateSelectionSummary();

            if (this._detailsView && !this._detailsView.$el.hasClass("disappear")) {
                this._updateDetailsView(null);
            }
        },

        _onClickSelectAll: function(e) {
            const hiddenFiles = this.$fileList.find("tr.hidden");
            const checked = e.target.checked;

            if (hiddenFiles.length > 0) {
                e.target.indeterminate = checked;
            } else {
                e.target.indeterminate = false;
            }

            this.$fileList.find("td.selection > .selectCheckBox:visible").prop("checked", checked).closest("tr").toggleClass("selected", checked);

            if (checked) {
                for (let i = 0; i < this.files.length; i++) {
                    const fileData = this.files[i];
                    const fileRow = this.$fileList.find("tr[data-id=" + fileData.id + "]");

                    if (!fileRow.hasClass("hidden") && _.isUndefined(this._selectedFiles[fileData.id])) {
                        this._selectedFiles[fileData.id] = fileData;
                        this._selectionSummary.add(fileData);
                    }
                }
            } else {
                if (hiddenFiles.length > 0) {
                    const visibleFiles = this.$fileList.find("tr:not(.hidden)");
                    const self = this;

                    visibleFiles.each(function() {
                        const id = parseInt($(this).data("id"));

                        if (!_.isUndefined(self._selectedFiles[id])) {
                            const fileData = self._selectedFiles[id];
                            delete self._selectedFiles[fileData.id];
                            self._selectionSummary.remove(fileData);
                        }
                    });
                } else {
                    this._selectedFiles = {};
                    this._selectionSummary.clear();
                }
            }

            this.updateSelectionSummary();

            if (this._detailsView && !this._detailsView.$el.hasClass("disappear")) {
                this._updateDetailsView(null);
            }
        },

        _onClickDownloadSelected: function(event) {
            let files;
            const self = this;
            let dir = this.getCurrentDirectory();

            if (this.isAllSelected() && this.getSelectedFiles().length > 1) {
                files = OC.basename(dir);
                dir = OC.dirname(dir) || "/";
            } else {
                files = _.pluck(this.getSelectedFiles(), "name");
            }

            if (this.fileMultiSelectMenu.isDisabled("download")) {
                return false;
            }

            this.fileMultiSelectMenu.toggleLoading("download", true);

            const disableLoadingState = function() {
                self.fileMultiSelectMenu.toggleLoading("download", false);
            };

            if (this.getSelectedFiles().length > 1) {
                OCA.Files.Files.handleDownload(this.getDownloadUrl(files, dir, true), disableLoadingState);
            } else {
                const first = this.getSelectedFiles()[0];
                OCA.Files.Files.handleDownload(this.getDownloadUrl(first.name, dir, true), disableLoadingState);
            }

            event.preventDefault();
        },

        _onClickCopyMoveSelected: function(event) {
            let files;
            const self = this;
            files = _.pluck(this.getSelectedFiles(), "name");

            if (this.fileMultiSelectMenu.isDisabled("copyMove")) {
                return false;
            }

            const disableLoadingState = function() {
                self.fileMultiSelectMenu.toggleLoading("copyMove", false);
            };

            const actions = this.isSelectedMovable() ? OC.dialogs.FILEPICKER_TYPE_COPY_MOVE : OC.dialogs.FILEPICKER_TYPE_COPY;
            let dialogDir = self.getCurrentDirectory();

            if (typeof self.dirInfo.dirLastCopiedTo !== "undefined") {
                dialogDir = self.dirInfo.dirLastCopiedTo;
            }

            OC.dialogs.filepicker(t("files", "Choose target folder"), function(targetPath, type) {
                self.fileMultiSelectMenu.toggleLoading("copyMove", true);

                if (type === OC.dialogs.FILEPICKER_TYPE_COPY) {
                    self.copy(files, targetPath, disableLoadingState);
                }

                if (type === OC.dialogs.FILEPICKER_TYPE_MOVE) {
                    self.move(files, targetPath, disableLoadingState);
                }

                self.dirInfo.dirLastCopiedTo = targetPath;
            }, false, "httpd/unix-directory", true, actions, dialogDir);

            event.preventDefault();
        },

        _onClickDeleteSelected: function(event) {
            let files = null;

            if (!this.isAllSelected()) {
                files = _.pluck(this.getSelectedFiles(), "name");
            }

            this.do_delete(files);
            event.preventDefault();
        },

        _onClickTagSelected: function(event) {
            const self = this;
            event.preventDefault();
            let commonTags = [];
            const selectedFiles = _.pluck(this.getSelectedFiles(), "id");
            const tagCollections = [];
            const fetchTagPromises = [];

            selectedFiles.forEach(function(fileId) {
                const deferred = new $.Deferred();

                const tagCollection = new OC.SystemTags.SystemTagsMappingCollection([], {
                    objectType: "files",
                    objectId: fileId
                });

                tagCollections.push(tagCollection);

                tagCollection.fetch({
                    success: function() {
                        deferred.resolve("success");
                    },

                    error: function() {
                        deferred.resolve("failed");
                    }
                });

                fetchTagPromises.push(deferred);
            });

            if (!self._inputView) {
                self._inputView = new OC.SystemTags.SystemTagsInputField({
                    multiple: true,
                    allowActions: true,
                    allowCreate: true,
                    isAdmin: OC.isUserAdmin()
                });

                self._inputView.on("select", self._onSelectTag, self);
                self._inputView.on("deselect", self._onDeselectTag, self);
                self._inputView.render();

                self.tagsTitle = $(
                    "<h3>" + t("files", "Please select tag(s) to add to the selection") + "</h3>"
                );

                self.tagsSubmit = $("<button>" + t("files", "Apply tag(s) to selection") + "</button>");
                self.tagsContainer = $("<tr id=\"tag_multiple_files_container\"></tr>");
                self.tagsTitle.appendTo(self.tagsContainer);
                self.tagsContainer.append(self._inputView.el);
                self.tagsSubmit.appendTo(self.tagsContainer);
                self.$table.find("thead").append(self.tagsContainer);

                self.tagsSubmit.on("click", function(ev) {
                    self._onClickDocument(ev);
                });
            }

            self._inputView.$el.addClass("icon-loading");
            self.tagsContainer.show();

            Promise.all(fetchTagPromises).then(function() {
                commonTags = _.intersection.apply(null, tagCollections.map(function(tagCollection) {
                    return tagCollection.getTagIds();
                }));

                self._inputView.setValues(commonTags);
                self._inputView.$el.removeClass("icon-loading");

                $(document).on("click", function(ev) {
                    self._onClickDocument(ev);
                });
            });
        },

        _onClickDocument: function(ev) {
            if (!$(ev.target).closest("#editor_container").length) {
                this._inputView.setValues([]);
                this.tagsContainer.hide();
                $(document).off("click", this._onClickDocument);
            }
        },

        _onSelectTag: function(tagModel) {
            const selectedFiles = _.pluck(this.getSelectedFiles(), "id");

            if (!_.isArray(selectedFiles)) {
                return;
            }

            selectedFiles.forEach(function(fileId) {
                $.ajax({
                    url: OC.linkToRemote("dav") + "/systemtags-relations/files/" + fileId + "/" + tagModel.attributes.id,
                    type: "PUT"
                });
            });
        },

        _onDeselectTag: function(tagId) {
            const selectedFiles = _.pluck(this.getSelectedFiles(), "id");

            if (!_.isArray(selectedFiles)) {
                return;
            }

            selectedFiles.forEach(function(fileId) {
                $.ajax({
                    url: OC.linkToRemote("dav") + "/systemtags-relations/files/" + fileId + "/" + tagId,
                    type: "DELETE"
                });
            });
        },

        _onClickHeader: function(e) {
            if (this.$table.hasClass("multiselect")) {
                return;
            }

            let $target = $(e.target);
            let sort;

            if (!$target.is("a")) {
                $target = $target.closest("a");
            }

            sort = $target.attr("data-sort");

            if (sort && this._allowSorting) {
                if (this._sort === sort) {
                    this.setSort(sort, this._sortDirection === "desc" ? "asc" : "desc", true, true);
                } else {
                    if (sort === "name") {
                        this.setSort(sort, "asc", true, true);
                    } else {
                        this.setSort(sort, "desc", true, true);
                    }
                }
            }
        },

        _onClickBreadCrumb: function(e) {
            const $el = $(e.target).closest(".crumb, .crumblist");
            const $targetDir = $el.data("dir");

            if ($targetDir !== undefined && e.which === 1) {
                e.preventDefault();
                this.changeDirectory($targetDir, true, true);
            }
        },

        _onScroll: function(e) {
            if (this.$container.scrollTop() + this.$container.height() > this.$el.height() - 300) {
                this._nextPage(true);
            }
        },

        _onDropOnBreadCrumb: function(event, ui) {
            const self = this;
            let $target = $(event.target);

            if (!$target.is(".crumb, .crumblist")) {
                $target = $target.closest(".crumb, .crumblist");
            }

            const targetPath = $(event.target).data("dir");
            let dir = this.getCurrentDirectory();

            while (dir.substr(0, 1) === "/") {
                dir = dir.substr(1);
            }

            dir = "/" + dir;

            if (dir.substr(-1, 1) !== "/") {
                dir = dir + "/";
            }

            if (targetPath === dir || targetPath + "/" === dir) {
                return;
            }

            let files = this.getSelectedFiles();

            if (files.length === 0) {
                files = _.map(ui.helper.find("tr"), function(el) {
                    return self.elementToFile($(el));
                });
            }

            const movePromise = this.move(_.pluck(files, "name"), targetPath);

            setTimeout(function() {
                self.$el.find("td.filename.ui-droppable").droppable("enable");
            }, 10);

            return movePromise;
        },

        setPageTitle: function(title) {
            if (title) {
                title += " - ";
            } else {
                title = "";
            }

            title += this.appName;
            window.document.title = title + " - " + OC.theme.title;
            return true;
        },

        findFile: function(fileName) {
            return (_.find(this.files, function(aFile) {
                return aFile.name === fileName;
            }) || null);
        },

        findFileEl: function(fileName) {
            return this.$fileList.find("tr").filterAttr("data-file", fileName);
        },

        elementToFile: function($el) {
            $el = $($el);

            const data = {
                id: parseInt($el.attr("data-id"), 10),
                name: $el.attr("data-file"),
                mimetype: $el.attr("data-mime"),
                mtime: parseInt($el.attr("data-mtime"), 10),
                type: $el.attr("data-type"),
                etag: $el.attr("data-etag"),
                quotaAvailableBytes: $el.attr("data-quota"),
                permissions: parseInt($el.attr("data-permissions"), 10),
                hasPreview: $el.attr("data-has-preview") === "true",
                isEncrypted: $el.attr("data-e2eencrypted") === "true"
            };

            const size = $el.attr("data-size");

            if (size) {
                data.size = parseInt(size, 10);
            }

            const icon = $el.attr("data-icon");

            if (icon) {
                data.icon = icon;
            }

            const mountType = $el.attr("data-mounttype");

            if (mountType) {
                data.mountType = mountType;
            }

            const path = $el.attr("data-path");

            if (path) {
                data.path = path;
            }

            return data;
        },

        _nextPage: function(animate) {
            let index = this.$fileList.children().length;
            let count = this.pageSize();
            let hidden;
            let tr;
            let fileData;
            const newTrs = [];
            const isAllSelected = this.isAllSelected();
            const showHidden = this._filesConfig.get("showhidden");

            if (index >= this.files.length) {
                return false;
            }

            while (count > 0 && index < this.files.length) {
                fileData = this.files[index];

                if (this._filter) {
                    hidden = fileData.name.toLowerCase().indexOf(this._filter.toLowerCase()) === -1;
                } else {
                    hidden = false;
                }

                tr = this._renderRow(fileData, {
                    updateSummary: false,
                    silent: true,
                    hidden: hidden
                });

                this.$fileList.append(tr);

                if (isAllSelected || this._selectedFiles[fileData.id]) {
                    tr.addClass("selected");
                    tr.find(".selectCheckBox").prop("checked", true);
                }

                if (animate) {
                    tr.addClass("appear transparent");
                }

                newTrs.push(tr);
                index++;

                if (showHidden || !tr.hasClass("hidden-file")) {
                    count--;
                }
            }

            if (newTrs.length > 0) {
                this.$fileList.trigger($.Event("fileActionsReady", {
                    fileList: this,
                    $files: newTrs
                }));
            }

            if (animate) {
                window.setTimeout(function() {
                    for (let i = 0; i < newTrs.length; i++) {
                        newTrs[i].removeClass("transparent");
                    }
                }, 0);
            }

            return newTrs;
        },

        _onFileActionsUpdated: function() {
            const self = this;
            const $files = this.$fileList.find("tr");

            if (!$files.length) {
                return;
            }

            $files.each(function() {
                self.fileActions.display($(this).find("td.filename"), false, self);
            });

            this.$fileList.trigger($.Event("fileActionsReady", {
                fileList: this,
                $files: $files
            }));
        },

        registerMultiSelectFileAction: function(fileAction) {
            if (typeof this.multiSelectMenuItems === "undefined") {
                return;
            }

            this.multiSelectMenuItems.push(fileAction);
            this._updateMultiSelectFileActions();
        },

        _updateMultiSelectFileActions: function() {
            if (typeof this.multiSelectMenuItems === "undefined") {
                return;
            }

            this.fileMultiSelectMenu = new OCA.Files.FileMultiSelectMenu(this.multiSelectMenuItems.sort(function(a, b) {
                return a.order - b.order;
            }));

            this.fileMultiSelectMenu.render();
            this.$el.find(".selectedActions .filesSelectMenu").remove();
            this.$el.find(".selectedActions").append(this.fileMultiSelectMenu.$el);
        },

        setFiles: function(filesArray) {
            const self = this;
            this.files = filesArray;
            this.$fileList.empty();

            if (this._allowSelection) {
                this.$el.addClass("has-selection");
            }

            this.$el.find(".select-all").prop("checked", false);
            this.isEmpty = this.files.length === 0;
            this._nextPage();
            this.updateEmptyContent();
            this.fileSummary.calculate(this.files);
            this._selectedFiles = {};
            this._selectionSummary.clear();
            this.updateSelectionSummary();
            $(window).scrollTop(0);
            this.$fileList.trigger(jQuery.Event("updated"));

            _.defer(function() {
                self.$el.closest("#app-content").trigger(jQuery.Event("apprendered"));
            });
        },

        _isHiddenFile: function(file) {
            return file.name && file.name.charAt(0) === ".";
        },

        _getIconUrl: function(fileInfo) {
            const mimeType = fileInfo.mimetype || "application/octet-stream";

            if (mimeType === "httpd/unix-directory") {
                if (fileInfo.mountType === "shared" || fileInfo.mountType === "shared-root") {
                    return OC.MimeType.getIconUrl("dir-shared");
                } else if (fileInfo.mountType === "external-root") {
                    return OC.MimeType.getIconUrl("dir-external");
                } else if (fileInfo.mountType !== undefined && fileInfo.mountType !== "") {
                    return OC.MimeType.getIconUrl("dir-" + fileInfo.mountType);
                } else if (fileInfo.shareTypes && (fileInfo.shareTypes.indexOf(OC.Share.SHARE_TYPE_LINK) > -1 || fileInfo.shareTypes.indexOf(OC.Share.SHARE_TYPE_EMAIL) > -1)) {
                    return OC.MimeType.getIconUrl("dir-public");
                } else if (fileInfo.shareTypes && fileInfo.shareTypes.length > 0) {
                    return OC.MimeType.getIconUrl("dir-shared");
                }

                return OC.MimeType.getIconUrl("dir");
            }

            return OC.MimeType.getIconUrl(mimeType);
        },

        _createRow: function(fileData, options) {
            let td;
            let simpleSize;
            let basename;
            let extension;
            let sizeColor;
            let icon = fileData.icon || this._getIconUrl(fileData);
            let name = fileData.name;
            const type = fileData.type || "file";
            let mtime = parseInt(fileData.mtime, 10);
            let mime = fileData.mimetype;
            let path = fileData.path;
            let dataIcon = null;
            let linkUrl;
            options = options || {};

            if (isNaN(mtime)) {
                mtime = new Date().getTime();
            }

            if (type === "dir") {
                mime = mime || "httpd/unix-directory";

                if (fileData.isEncrypted) {
                    icon = OC.MimeType.getIconUrl("dir-encrypted");
                    dataIcon = icon;
                } else if (fileData.mountType && fileData.mountType.indexOf("external") === 0) {
                    icon = OC.MimeType.getIconUrl("dir-external");
                    dataIcon = icon;
                }
            }

            let permissions = fileData.permissions;

            if (permissions === undefined || permissions === null) {
                permissions = this.getDirectoryPermissions();
            }

            const tr = $("<tr></tr>").attr({
                "data-id": fileData.id,
                "data-type": type,
                "data-size": fileData.size,
                "data-file": name,
                "data-mime": mime,
                "data-mtime": mtime,
                "data-etag": fileData.etag,
                "data-quota": fileData.quotaAvailableBytes,
                "data-permissions": permissions,
                "data-has-preview": fileData.hasPreview !== false,
                "data-e2eencrypted": fileData.isEncrypted === true
            });

            if (dataIcon) {
                tr.attr("data-icon", dataIcon);
            }

            if (fileData.mountType) {
                if (this.dirInfo.id) {
                    if (fileData.mountType === "shared" && this.dirInfo.mountType !== "shared" && this.dirInfo.mountType !== "shared-root") {
                        fileData.mountType = "shared-root";
                    } else if (fileData.mountType === "external" && this.dirInfo.mountType !== "external" && this.dirInfo.mountType !== "external-root") {
                        fileData.mountType = "external-root";
                    }
                }

                tr.attr("data-mounttype", fileData.mountType);
            }

            if (!_.isUndefined(path)) {
                tr.attr("data-path", path);
            } else {
                path = this.getCurrentDirectory();
            }

            if (this._allowSelection) {
                td = $("<td class=\"selection\"></td>");

                td.append(
                    "<input id=\"select-" + this.id + "-" + fileData.id + "\" type=\"checkbox\" class=\"selectCheckBox checkbox\" aria-describedby=\"innernametext_" + fileData.id + "\" /><label for=\"select-" + this.id + "-" + fileData.id + "\">" + "<span class=\"hidden-visually\">" + (fileData.type === "dir" ? t("files", "Select directory \"{dirName}\"", {
                        dirName: name
                    }) : t("files", "Select file \"{fileName}\"", {
                        fileName: name
                    })) + "</span>" + "</label>"
                );

                tr.append(td);
            }

            td = $("<td class=\"filename\"></td>");
            const spec = this.fileActions.getDefaultFileAction(mime, type, permissions);

            if (mime === "httpd/unix-directory") {
                linkUrl = this.linkTo(path + "/" + name);
            } else if (spec && spec.action) {
                linkUrl = this.getDefaultActionUrl(path, fileData.id);
            } else {
                linkUrl = this.getDownloadUrl(name, path, type === "dir");
            }

            const linkElem = $("<a></a>").attr({
                class: "name",
                href: linkUrl
            });

            if (this._defaultFileActionsDisabled) {
                linkElem.addClass("disabled");
            }

            linkElem.append(
                "<div class=\"thumbnail-wrapper\"><div class=\"thumbnail\" style=\"background-image:url(" + icon + ");\"></div></div>"
            );

            name = fileData.displayName || name;

            if (name.indexOf(".") === 0) {
                basename = "";
                extension = name;
            } else if (mime !== "httpd/unix-directory" && name.indexOf(".") !== -1) {
                basename = name.substr(0, name.lastIndexOf("."));
                extension = name.substr(name.lastIndexOf("."));
            } else {
                basename = name;
                extension = false;
            }

            const nameSpan = $("<span></span>").addClass("nametext");
            const innernameSpan = $("<span></span>").addClass("innernametext").text(basename).prop("title", basename).prop("id", `innernametext_${fileData.id}`);
            const conflictingItems = this.$fileList.find("tr[data-file=\"" + this._jqSelEscape(name) + "\"]");

            if (conflictingItems.length !== 0) {
                if (conflictingItems.length === 1) {
                    const $firstConflict = $(conflictingItems[0]);
                    let firstConflictPath = $firstConflict.attr("data-path") + "/";

                    if (firstConflictPath.charAt(0) === "/") {
                        firstConflictPath = firstConflictPath.substr(1);
                    }

                    if (firstConflictPath && firstConflictPath !== "/") {
                        $firstConflict.find("td.filename span.innernametext").prepend($("<span></span>").addClass("conflict-path").text(firstConflictPath));
                    }
                }

                let conflictPath = path + "/";

                if (conflictPath.charAt(0) === "/") {
                    conflictPath = conflictPath.substr(1);
                }

                if (path && path !== "/") {
                    nameSpan.append($("<span></span>").addClass("conflict-path").text(conflictPath));
                }
            }

            nameSpan.append(innernameSpan);
            linkElem.append(nameSpan);

            if (extension) {
                nameSpan.append($("<span></span>").addClass("extension").text(extension));
            }

            if (fileData.extraData) {
                if (fileData.extraData.charAt(0) === "/") {
                    fileData.extraData = fileData.extraData.substr(1);
                }

                nameSpan.addClass("extra-data").attr("title", fileData.extraData);
            }

            if (mime === "httpd/unix-directory") {
                linkElem.append($("<span></span>").attr({
                    class: "uploadtext",
                    currentUploads: 0
                }));
            }

            td.append(linkElem);
            tr.append(td);
            const enabledThemes = window.OCA?.Theming?.enabledThemes || [];
            const isDarkTheme = enabledThemes.length === 0 || enabledThemes[0] === "default" ? window.matchMedia("(prefers-color-scheme: dark)").matches : enabledThemes.join("").indexOf("dark") !== -1;

            try {
                const maxContrastHex = window.getComputedStyle(document.documentElement).getPropertyValue("--color-text-maxcontrast").trim();

                if (maxContrastHex.length < 4) {
                    throw Error();
                }

                var maxContrast = parseInt(maxContrastHex.substring(1, 3), 16);
            } catch (error) {
                var maxContrast = isDarkTheme ? 130 : 118;
            }

            if (typeof fileData.size !== "undefined" && fileData.size >= 0) {
                simpleSize = OC.Util.humanFileSize(parseInt(fileData.size, 10), true);
                sizeColor = Math.round(118 - Math.pow(fileData.size / (1024 * 1024), 2));

                if (sizeColor >= maxContrast) {
                    sizeColor = maxContrast;
                }

                if (isDarkTheme) {
                    sizeColor = Math.abs(sizeColor);

                    if (sizeColor < maxContrast) {
                        sizeColor = maxContrast;
                    }
                }
            } else {
                simpleSize = t("files", "Pending");
            }

            td = $("<td></td>").attr({
                class: "filesize",
                style: "color:rgb(" + sizeColor + "," + sizeColor + "," + sizeColor + ")"
            }).text(simpleSize);

            tr.append(td);
            let modifiedColor = Math.round(((new Date().getTime() - mtime) / 1000 / 60 / 60 / 24) * 5);

            if (modifiedColor >= maxContrast) {
                modifiedColor = maxContrast;
            }

            if (isDarkTheme) {
                modifiedColor = Math.abs(modifiedColor);

                if (modifiedColor < maxContrast) {
                    modifiedColor = maxContrast;
                }
            }

            let formatted;
            let text;

            if (mtime > 0) {
                formatted = OC.Util.formatDate(mtime);
                text = OC.Util.relativeModifiedDate(mtime);
            } else {
                formatted = t("files", "Unable to determine date");
                text = "?";
            }

            td = $("<td></td>").attr({
                class: "date"
            });

            td.append($("<span></span>").attr({
                class: "modified live-relative-timestamp",
                title: formatted,
                "data-timestamp": mtime,
                style: "color:rgb(" + modifiedColor + "," + modifiedColor + "," + modifiedColor + ")"
            }).text(text).tooltip({
                placement: "top"
            }));

            tr.find(".filesize").text(simpleSize);
            tr.append(td);
            return tr;
        },

        _jqSelEscape: function(expression) {
            if (expression) {
                return expression.replace(/[!"#$%&'()*+,.\/:;<=>?@\[\\\]^`{|}~]/g, "\\$&");
            }

            return null;
        },

        add: function(fileData, options) {
            const self = this;
            let index;
            let $tr;
            let $rows;
            let $insertionPoint;

            options = _.extend({
                animate: true
            }, options || {});

            $rows = this.$fileList.children();
            index = this._findInsertionIndex(fileData);

            if (index > this.files.length) {
                index = this.files.length;
            } else {
                $insertionPoint = $rows.eq(index);
            }

            if ($insertionPoint.length) {
                $tr = this._renderRow(fileData, options);
                $insertionPoint.before($tr);
            } else {
                if (index === $rows.length) {
                    $tr = this._renderRow(fileData, options);
                    this.$fileList.append($tr);
                }
            }

            this.isEmpty = false;
            this.files.splice(index, 0, fileData);

            if ($tr && options.animate) {
                $tr.addClass("appear transparent");

                window.setTimeout(function() {
                    $tr.removeClass("transparent");
                    self.$fileList.find("tr").removeClass("mouseOver");
                    $tr.addClass("mouseOver");
                });
            }

            if (options.scrollTo) {
                this.scrollTo(fileData.name);
            }

            if (typeof options.updateSummary === "undefined" || !!options.updateSummary) {
                this.fileSummary.add(fileData, true);
                this.updateEmptyContent();
            }

            return $tr;
        },

        _renderRow: function(fileData, options) {
            options = options || {};
            const type = fileData.type || "file";
            let mime = fileData.mimetype;
            const path = fileData.path || this.getCurrentDirectory();
            let permissions = parseInt(fileData.permissions, 10) || 0;
            const isEndToEndEncrypted = type === "dir" && fileData.isEncrypted;

            if (!isEndToEndEncrypted && fileData.isShareMountPoint) {
                permissions = permissions | OC.PERMISSION_UPDATE;
            }

            if (type === "dir") {
                mime = mime || "httpd/unix-directory";
            }

            const tr = this._createRow(fileData, options);
            const filenameTd = tr.find("td.filename");

            if (this._dragOptions && permissions & OC.PERMISSION_DELETE) {
                filenameTd.draggable(this._dragOptions);
            }

            if (this._folderDropOptions && mime === "httpd/unix-directory") {
                tr.droppable(this._folderDropOptions);
            }

            if (options.hidden) {
                tr.addClass("hidden");
            }

            if (this._isHiddenFile(fileData)) {
                tr.addClass("hidden-file");
            }

            this.fileActions.display(filenameTd, !options.silent, this);

            if (mime !== "httpd/unix-directory" && fileData.hasPreview !== false) {
                const iconDiv = filenameTd.find(".thumbnail");

                if (typeof options.animate === "undefined" || !!options.animate) {
                    this.lazyLoadPreview({
                        fileId: fileData.id,
                        path: path + "/" + fileData.name,
                        mime: mime,
                        etag: fileData.etag,

                        callback: function(url) {
                            iconDiv.css("background-image", "url(\"" + url + "\")");
                        }
                    });
                } else {
                    const urlSpec = {
                        file: path + "/" + fileData.name,
                        c: fileData.etag
                    };

                    let previewUrl = this.generatePreviewUrl(urlSpec);
                    previewUrl = previewUrl.replace(/\(/g, "%28").replace(/\)/g, "%29");
                    iconDiv.css("background-image", "url(\"" + previewUrl + "\")");
                }
            }

            return tr;
        },

        getCurrentDirectory: function() {
            return this._currentDirectory || "/";
        },

        getDirectoryPermissions: function() {
            return this && this.dirInfo && this.dirInfo.permissions ? this.dirInfo.permissions : parseInt(this.$el.find("#permissions").val(), 10);
        },

        changeDirectory: function(targetDir, changeUrl, force, fileId, changedThroughUrl) {
            const self = this;
            const currentDir = this.getCurrentDirectory();
            targetDir = targetDir || "/";

            if (!force && currentDir === targetDir) {
                return;
            }

            this._setCurrentDir(targetDir, changeUrl, fileId, changedThroughUrl);
            this._uploads = {};

            return this.reload().then(function(success) {
                if (!success) {
                    self.changeDirectory(currentDir, true);
                }
            });
        },

        linkTo: function(dir) {
            return OC.linkTo("files", "index.php") + "?dir=" + encodeURIComponent(dir).replace(/%2F/g, "/");
        },

        _isValidPath: function(path) {
            const sections = path.split("/");

            for (let i = 0; i < sections.length; i++) {
                if (sections[i] === "..") {
                    return false;
                }
            }

            return path.toLowerCase().indexOf(decodeURI("%0a")) === -1 && path.toLowerCase().indexOf(decodeURI("%00")) === -1;
        },

        _setCurrentDir: function(targetDir, changeUrl, fileId, changedThroughUrl) {
            targetDir = targetDir.replace(/\\/g, "/");

            if (!this._isValidPath(targetDir)) {
                targetDir = "/";
                changeUrl = true;
            }

            const previousDir = this.getCurrentDirectory();
            const baseDir = OC.basename(targetDir);

            if (baseDir !== "") {
                this.setPageTitle(baseDir);
            } else {
                this.setPageTitle();
            }

            if (targetDir.length > 0 && targetDir[0] !== "/") {
                targetDir = "/" + targetDir;
            }

            this._currentDirectory = targetDir;

            if (changeUrl !== false) {
                const params = {
                    dir: targetDir,
                    previousDir: previousDir
                };

                if (fileId) {
                    params.fileId = fileId;
                }

                params.changedThroughUrl = changedThroughUrl;
                this.$el.trigger(jQuery.Event("changeDirectory", params));
            }

            this.breadcrumb.setDirectory(this.getCurrentDirectory());
        },

        setSort: function(sort, direction, update, persist) {
            const comparator = FileList.Comparators[sort] || FileList.Comparators.name;
            this._sort = sort;
            this._sortDirection = direction === "desc" ? "desc" : "asc";

            this._sortComparator = function(fileInfo1, fileInfo2) {
                const isFavorite = function(fileInfo) {
                    return fileInfo.tags && fileInfo.tags.indexOf(OC.TAG_FAVORITE) >= 0;
                };

                if (isFavorite(fileInfo1) && !isFavorite(fileInfo2)) {
                    return -1;
                } else if (!isFavorite(fileInfo1) && isFavorite(fileInfo2)) {
                    return 1;
                }

                return direction === "asc" ? comparator(fileInfo1, fileInfo2) : -comparator(fileInfo1, fileInfo2);
            };

            this.$el.find("thead th .sort-indicator").removeClass(this.SORT_INDICATOR_ASC_CLASS).removeClass(this.SORT_INDICATOR_DESC_CLASS).toggleClass("hidden", true).addClass(this.SORT_INDICATOR_DESC_CLASS);

            this.$el.find("thead th.column-" + sort + " .sort-indicator").removeClass(this.SORT_INDICATOR_ASC_CLASS).removeClass(this.SORT_INDICATOR_DESC_CLASS).toggleClass("hidden", false).addClass(
                direction === "desc" ? this.SORT_INDICATOR_DESC_CLASS : this.SORT_INDICATOR_ASC_CLASS
            );

            if (update) {
                if (this._clientSideSort) {
                    this.files.sort(this._sortComparator);
                    this.setFiles(this.files);
                } else {
                    this.reload();
                }
            }

            if (persist && OC.getCurrentUser().uid) {
                $.post(OC.generateUrl("/apps/files/api/v1/sorting"), {
                    mode: sort,
                    direction: direction
                });
            }
        },

        _getWebdavProperties: function() {
            return [].concat(this.filesClient.getPropfindProperties());
        },

        reload: function() {
            this._selectedFiles = {};
            this._selectionSummary.clear();

            if (this._currentFileModel) {
                this._currentFileModel.off();
            }

            this._currentFileModel = null;
            this.$el.find(".select-all").prop("checked", false);
            this.showMask();

            this._reloadCall = this.filesClient.getFolderContents(this.getCurrentDirectory(), {
                includeParent: true,
                properties: this._getWebdavProperties()
            });

            if (this._detailsView) {
                this._updateDetailsView(null);
            }

            this._setCurrentDir(this.getCurrentDirectory(), false);
            const callBack = this.reloadCallback.bind(this);
            return this._reloadCall.then(callBack, callBack);
        },

        reloadCallback: function(status, result) {
            delete this._reloadCall;
            this.hideMask();

            if (status === 401) {
                location.reload();
            }

            if (status === 403) {
                this.changeDirectory("/");

                OC.Notification.show(t("files", "This operation is forbidden"), {
                    type: "error"
                });

                return false;
            }

            if (status === 500) {
                this.changeDirectory("/");

                OC.Notification.show(t(
                    "files",
                    "This directory is unavailable, please check the logs or contact the administrator"
                ), {
                    type: "error"
                });

                return false;
            }

            if (status === 503) {
                if (this.getCurrentDirectory() !== "/") {
                    this.changeDirectory("/");

                    OC.Notification.show(t("files", "Storage is temporarily not available"), {
                        type: "error"
                    });
                }

                return false;
            }

            if (status === 400 || status === 404 || status === 405) {
                this.changeDirectory("/");
                return false;
            }

            if (status === 0) {
                return true;
            }

            this.updateStorageStatistics(true);
            this.dirInfo = result.shift();
            this.breadcrumb.setDirectoryInfo(this.dirInfo);

            if (this.dirInfo.permissions) {
                this._updateDirectoryPermissions();
            }

            result.sort(this._sortComparator);
            this.setFiles(result);

            if (this.dirInfo) {
                OCA.Files.App && OCA.Files.App.updateCurrentFileList(this);
                const newFileId = this.dirInfo.id;

                const params = {
                    dir: this.getCurrentDirectory()
                };

                if (newFileId) {
                    params.fileId = newFileId;
                }

                this.$el.trigger(jQuery.Event("afterChangeDirectory", params));
            }

            return true;
        },

        updateStorageStatistics: function(force) {
            OCA.Files.Files.updateStorageStatistics(this.getCurrentDirectory(), force);
        },

        updateStorageQuotas: function() {
            OCA.Files.Files.updateStorageQuotas();
        },

        getAjaxUrl: function(action, params) {
            return OCA.Files.Files.getAjaxUrl(action, params);
        },

        getDownloadUrl: function(files, dir, isDir) {
            return OCA.Files.Files.getDownloadUrl(files, dir || this.getCurrentDirectory(), isDir);
        },

        getDefaultActionUrl: function(path, id) {
            return this.linkTo(path) + "&openfile=" + id;
        },

        getUploadUrl: function(fileName, dir) {
            if (_.isUndefined(dir)) {
                dir = this.getCurrentDirectory();
            }

            const pathSections = dir.split("/");

            if (!_.isUndefined(fileName)) {
                pathSections.push(fileName);
            }

            let encodedPath = "";

            _.each(pathSections, function(section) {
                if (section !== "") {
                    encodedPath += "/" + encodeURIComponent(section);
                }
            });

            return OC.linkToRemoteBase("webdav") + encodedPath;
        },

        generatePreviewUrl: function(urlSpec) {
            urlSpec = urlSpec || {};

            if (!urlSpec.x) {
                urlSpec.x = this.$table.data("preview-x") || 250;
            }

            if (!urlSpec.y) {
                urlSpec.y = this.$table.data("preview-y") || 250;
            }

            urlSpec.x *= window.devicePixelRatio;
            urlSpec.y *= window.devicePixelRatio;
            urlSpec.x = Math.ceil(urlSpec.x);
            urlSpec.y = Math.ceil(urlSpec.y);
            urlSpec.forceIcon = 0;
            urlSpec.a = this._filesConfig.get("cropimagepreviews") ? 0 : 1;

            if (typeof urlSpec.fileId !== "undefined") {
                delete urlSpec.file;
                return OC.generateUrl("/core/preview?") + $.param(urlSpec);
            } else {
                delete urlSpec.fileId;
                return OC.generateUrl("/core/preview.png?") + $.param(urlSpec);
            }
        },

        lazyLoadPreview: function(options) {
            const self = this;
            const fileId = options.fileId;
            const path = options.path;
            const mime = options.mime;
            const ready = options.callback;
            const etag = options.etag;
            const iconURL = OC.MimeType.getIconUrl(mime);
            let previewURL;
            const urlSpec = {};
            ready(iconURL);
            urlSpec.fileId = fileId;
            urlSpec.file = OCA.Files.Files.fixPath(path);

            if (options.x) {
                urlSpec.x = options.x;
            }

            if (options.y) {
                urlSpec.y = options.y;
            }

            if (options.a) {
                urlSpec.a = options.a;
            }

            if (options.mode) {
                urlSpec.mode = options.mode;
            }

            if (etag) {
                urlSpec.c = etag;
            }

            previewURL = self.generatePreviewUrl(urlSpec);
            previewURL = previewURL.replace(/\(/g, "%28").replace(/\)/g, "%29");
            const img = new Image();

            img.onload = function() {
                if (img.width > 5) {
                    ready(previewURL, img);
                } else if (options.error) {
                    options.error();
                }
            };

            if (options.error) {
                img.onerror = options.error;
            }

            img.src = previewURL;
        },

        _updateDirectoryPermissions: function() {
            const isCreatable = (this.dirInfo.permissions & OC.PERMISSION_CREATE) !== 0 && this.$el.find("#free_space").val() !== "0";
            this.$el.find("#permissions").val(this.dirInfo.permissions);
            this.$el.find(".creatable").toggleClass("hidden", !isCreatable);
            this.$el.find(".notCreatable").toggleClass("hidden", isCreatable);
        },

        showActions: function(show) {
            this.$el.find(".actions").toggleClass("hidden", !show);

            if (show) {
                const permissions = this.getDirectoryPermissions();
                const isCreatable = (permissions & OC.PERMISSION_CREATE) !== 0;
                this.$el.find(".creatable").toggleClass("hidden", !isCreatable);
                this.$el.find(".notCreatable").toggleClass("hidden", isCreatable);
                this.$el.find(".files-controls .crumb").remove();
                this.breadcrumb.render();
            } else {
                this.$el.find(".creatable, .notCreatable").addClass("hidden");
            }
        },

        setViewerMode: function(show) {
            this.showActions(!show);
            this.$el.find(".files-filestable").toggleClass("hidden", show);

            this.$el.trigger(new $.Event("changeViewerMode", {
                viewerModeEnabled: show
            }));
        },

        remove: function(name, options) {
            options = options || {};
            const fileEl = this.findFileEl(name);

            const fileData = _.findWhere(this.files, {
                name: name
            });

            if (!fileData) {
                return;
            }

            const fileId = fileData.id;

            if (this._selectedFiles[fileId]) {
                this._selectFileEl(fileEl, false);
                this.updateSelectionSummary();
            }

            if (this._selectedFiles[fileId]) {
                delete this._selectedFiles[fileId];
                this._selectionSummary.remove(fileData);
                this.updateSelectionSummary();
            }

            const index = this.files.findIndex(function(el) {
                return el.name == name;
            });

            this.files.splice(index, 1);
            this.isEmpty = !this.files.length;

            if (typeof options.updateSummary === "undefined" || !!options.updateSummary) {
                this.updateEmptyContent();

                this.fileSummary.remove({
                    type: fileData.type,
                    size: fileData.size
                }, true);
            }

            if (!fileEl.length) {
                return null;
            }

            if (this._dragOptions && fileEl.data("permissions") & OC.PERMISSION_DELETE) {
                fileEl.find("td.filename").draggable("destroy");
            }

            if (this._currentFileModel && this._currentFileModel.get("id") === fileId) {
                this._currentFileModel.trigger("destroy");
                this._updateDetailsView(null);
            }

            fileEl.remove();
            const lastIndex = this.$fileList.children().length;

            if (lastIndex < this.files.length && lastIndex < this.pageSize()) {
                this._nextPage(true);
            }

            return fileEl;
        },

        _findInsertionIndex: function(fileData) {
            let index = 0;

            while (index < this.files.length && this._sortComparator(fileData, this.files[index]) > 0) {
                index++;
            }

            return index;
        },

        move: function(fileNames, targetPath, callback, dir) {
            const self = this;
            dir = typeof dir === "string" ? dir : this.getCurrentDirectory();

            if (dir.charAt(dir.length - 1) !== "/") {
                dir += "/";
            }

            const target = OC.basename(targetPath);

            if (!_.isArray(fileNames)) {
                fileNames = [fileNames];
            }

            const moveFileFunction = function(fileName) {
                const $tr = self.findFileEl(fileName);
                self.showFileBusyState($tr, true);

                if (targetPath.charAt(targetPath.length - 1) !== "/") {
                    targetPath = targetPath + "/";
                }

                return self.filesClient.move(dir + fileName, targetPath + fileName).done(function() {
                    if (OC.joinPaths(self.getCurrentDirectory(), "/") === OC.joinPaths(dir, "/")) {
                        const oldFile = self.findFileEl(target);
                        const newFile = self.findFileEl(fileName);
                        const oldSize = oldFile.data("size");
                        const newSize = oldSize + newFile.data("size");
                        oldFile.data("size", newSize);
                        oldFile.find("td.filesize").text(OC.Util.humanFileSize(newSize));
                        self.remove(fileName);
                    }
                }).fail(function(status) {
                    if (status === 412) {
                        OC.Notification.show(t("files", "Could not move \"{file}\", target exists", {
                            file: fileName
                        }), {
                            type: "error"
                        });
                    } else {
                        OC.Notification.show(t("files", "Could not move \"{file}\"", {
                            file: fileName
                        }), {
                            type: "error"
                        });
                    }
                }).always(function() {
                    self.showFileBusyState($tr, false);
                });
            };

            return this.reportOperationProgress(fileNames, moveFileFunction, callback).then(function() {
                self.updateStorageStatistics();
                self.updateStorageQuotas();
            });
        },

        _reflect: function(promise) {
            return promise.then(function(v) {
                return {};
            }, function(e) {
                return {};
            });
        },

        reportOperationProgress: function(fileNames, operationFunction, callback) {
            const self = this;
            self._operationProgressBar.showProgressBar(false);
            const mcSemaphore = new OCA.Files.Semaphore(5);
            let counter = 0;

            const promises = _.map(fileNames, function(arg) {
                return mcSemaphore.acquire().then(function() {
                    return operationFunction(arg).always(function() {
                        mcSemaphore.release();
                        counter++;
                        self._operationProgressBar.setProgressBarValue((100.0 * counter) / fileNames.length);
                    });
                });
            });

            return Promise.all(_.map(promises, self._reflect)).then(function() {
                if (callback) {
                    callback();
                }

                self._operationProgressBar.hideProgressBar();
            });
        },

        copy: function(fileNames, targetPath, callback, dir) {
            const self = this;
            const filesToNotify = [];
            let count = 0;
            dir = typeof dir === "string" ? dir : this.getCurrentDirectory();

            if (dir.charAt(dir.length - 1) !== "/") {
                dir += "/";
            }

            const target = OC.basename(targetPath);

            if (!_.isArray(fileNames)) {
                fileNames = [fileNames];
            }

            const copyFileFunction = function(fileName) {
                const $tr = self.findFileEl(fileName);
                self.showFileBusyState($tr, true);

                if (targetPath.charAt(targetPath.length - 1) !== "/") {
                    targetPath = targetPath + "/";
                }

                let targetPathAndName = targetPath + fileName;

                if (dir + fileName === targetPathAndName) {
                    const dotIndex = targetPathAndName.indexOf(".");

                    if (dotIndex > 1) {
                        let leftPartOfName = targetPathAndName.substr(0, dotIndex);
                        let fileNumber = leftPartOfName.match(/\d+/);
                        const copyNameLocalized = t("files", "copy");

                        if (isNaN(fileNumber)) {
                            fileNumber++;
                            targetPathAndName = targetPathAndName.replace(/(?=\.[^.]+$)/g, " (" + copyNameLocalized + " " + fileNumber + ")");
                        } else {
                            let maxNum = 1;

                            if (self.files !== null) {
                                leftPartOfName = leftPartOfName.replace("/", "");
                                leftPartOfName = leftPartOfName.replace(new RegExp("\\(" + copyNameLocalized + "( \\d+)?\\)"), "");

                                for (let j = 0; j < self.files.length; j++) {
                                    const cName = self.files[j].name;

                                    if (cName.indexOf(leftPartOfName) > -1) {
                                        if (cName.indexOf("(" + copyNameLocalized + ")") > 0) {
                                            targetPathAndName = targetPathAndName.replace(new RegExp(" \\(" + copyNameLocalized + "\\)"), "");

                                            if (maxNum == 1) {
                                                maxNum = 2;
                                            }
                                        } else {
                                            const cFileNumber = cName.match(new RegExp("\\(" + copyNameLocalized + " (\\d+)\\)"));

                                            if (cFileNumber && parseInt(cFileNumber[1]) >= maxNum) {
                                                maxNum = parseInt(cFileNumber[1]) + 1;
                                            }
                                        }
                                    }
                                }

                                targetPathAndName = targetPathAndName.replace(new RegExp(" \\(" + copyNameLocalized + " \\d+\\)"), "");
                            }

                            let extensionName = " (" + copyNameLocalized + " " + maxNum + ")";

                            if (maxNum == 1) {
                                extensionName = " (" + copyNameLocalized + ")";
                            }

                            targetPathAndName = targetPathAndName.replace(/(?=\.[^.]+$)/g, extensionName);
                        }
                    }
                }

                return self.filesClient.copy(dir + fileName, targetPathAndName).done(function() {
                    filesToNotify.push(fileName);

                    if (OC.joinPaths(self.getCurrentDirectory(), "/") === OC.joinPaths(dir, "/")) {
                        const oldFile = self.findFileEl(target);
                        const newFile = self.findFileEl(fileName);
                        const oldSize = oldFile.data("size");
                        const newSize = oldSize + newFile.data("size");
                        oldFile.data("size", newSize);
                        oldFile.find("td.filesize").text(OC.Util.humanFileSize(newSize));
                    }

                    self.reload();
                }).fail(function(status) {
                    if (status === 412) {
                        OC.Notification.show(t("files", "Could not copy \"{file}\", target exists", {
                            file: fileName
                        }), {
                            type: "error"
                        });
                    } else {
                        OC.Notification.show(t("files", "Could not copy \"{file}\"", {
                            file: fileName
                        }), {
                            type: "error"
                        });
                    }
                }).always(function() {
                    self.showFileBusyState($tr, false);
                    count++;

                    if (count === fileNames.length) {
                        if (targetPath.slice(0, 1) === "/") {
                            targetPath = targetPath.slice(1, targetPath.length);
                        }

                        if (targetPath.slice(-1) === "/") {
                            targetPath = targetPath.slice(0, -1);
                        }

                        if (filesToNotify.length > 0) {
                            if (filesToNotify.length === 1) {
                                OC.Notification.show(t("files", "Copied {origin} inside {destination}", {
                                    origin: filesToNotify[0],
                                    destination: targetPath
                                }), {
                                    timeout: 10
                                });
                            } else if (filesToNotify.length > 0 && filesToNotify.length < 3) {
                                OC.Notification.show(t("files", "Copied {origin} inside {destination}", {
                                    origin: filesToNotify.join(", "),
                                    destination: targetPath
                                }), {
                                    timeout: 10
                                });
                            } else {
                                OC.Notification.show(t(
                                    "files",
                                    "Copied {origin} and {nbfiles} other files inside {destination}",
                                    {
                                        origin: filesToNotify[0],
                                        nbfiles: filesToNotify.length - 1,
                                        destination: targetPath
                                    }
                                ), {
                                    timeout: 10
                                });
                            }
                        }
                    }
                });
            };

            return this.reportOperationProgress(fileNames, copyFileFunction, callback).then(function() {
                self.updateStorageStatistics();
                self.updateStorageQuotas();
            });
        },

        openLocalClient: function(path) {
            const scheme = "nc://";
            const command = "open";
            const uid = OC.getCurrentUser().uid;
            const url = scheme + command + "/" + uid + "@" + window.location.host + OC.encodePath(path);
            window.location.href = url;
        },

        updateRow: function($tr, fileInfo, options) {
            this.files.splice($tr.index(), 1);
            $tr.remove();

            options = _.extend({
                silent: true
            }, options);

            options = _.extend(options, {
                updateSummary: false
            });

            $tr = this.add(fileInfo, options);

            this.$fileList.trigger($.Event("fileActionsReady", {
                fileList: this,
                $files: $tr
            }));

            return $tr;
        },

        rename: function(oldName) {
            const self = this;
            let tr;
            let td;
            let input;
            let form;
            tr = this.findFileEl(oldName);
            const oldFileInfo = this.files[tr.index()];
            tr.data("renaming", true);
            td = tr.children("td.filename");
            input = $("<input type=\"text\" class=\"filename\"/>").val(oldName);
            form = $("<form></form>");
            form.append(input);
            td.children("a.name").children(":not(.thumbnail-wrapper)").hide();
            td.append(form);
            input.focus();
            let len = input.val().lastIndexOf(".");

            if (len === -1 || tr.data("type") === "dir") {
                len = input.val().length;
            }

            input.selectRange(0, len);

            const checkInput = function() {
                const filename = input.val();

                if (filename !== oldName) {
                    OCA.Files.Files.isFileNameValid(filename);

                    if (self.inList(filename)) {
                        throw t("files", "{newName} already exists", {
                            newName: filename
                        }, undefined, {
                            escape: false
                        });
                    }
                }

                return true;
            };

            function restore() {
                input.tooltip("hide");
                tr.data("renaming", false);
                form.remove();
                td.children("a.name").children(":not(.thumbnail-wrapper)").show();
            }

            function updateInList(fileInfo) {
                self.updateRow(tr, fileInfo);
                self._updateDetailsView(fileInfo.name, false);
            }

            form.submit(function(event) {
                event.stopPropagation();
                event.preventDefault();

                if (input.hasClass("error")) {
                    return;
                }

                try {
                    const newName = input.val().trim();
                    input.tooltip("hide");
                    form.remove();

                    if (newName !== oldName) {
                        checkInput();
                        self.showFileBusyState(tr, true);
                        tr.attr("data-file", newName);
                        let basename = newName;

                        if (newName.indexOf(".") > 0 && tr.data("type") !== "dir") {
                            basename = newName.substr(0, newName.lastIndexOf("."));
                        }

                        td.find("a.name span.nametext").text(basename);
                        td.children("a.name").children(":not(.thumbnail-wrapper)").show();
                        const path = tr.attr("data-path") || self.getCurrentDirectory();

                        self.filesClient.move(OC.joinPaths(path, oldName), OC.joinPaths(path, newName)).done(function() {
                            oldFileInfo.name = newName;
                            updateInList(oldFileInfo);
                        }).fail(function(status) {
                            if (status === 404) {
                                OC.Notification.show(
                                    t("files", "Could not rename \"{fileName}\", it does not exist any more", {
                                        fileName: oldName
                                    }),
                                    {
                                        timeout: 7,
                                        type: "error"
                                    }
                                );

                                self.remove(newName, {
                                    updateSummary: true
                                });

                                return;
                            } else if (status === 412) {
                                OC.Notification.show(t(
                                    "files",
                                    "The name \"{targetName}\" is already used in the folder \"{dir}\". Please choose a different name.",
                                    {
                                        targetName: newName,
                                        dir: self.getCurrentDirectory()
                                    }
                                ), {
                                    type: "error"
                                });
                            } else {
                                OC.Notification.show(t("files", "Could not rename \"{fileName}\"", {
                                    fileName: oldName
                                }), {
                                    type: "error"
                                });
                            }

                            updateInList(oldFileInfo);
                        });
                    } else {
                        self.files.splice(tr.index(), 1);
                        tr.remove();

                        tr = self.add(oldFileInfo, {
                            updateSummary: false,
                            silent: true
                        });

                        self.$fileList.trigger($.Event("fileActionsReady", {
                            fileList: self,
                            $files: $(tr)
                        }));
                    }
                } catch (error) {
                    input.attr("title", error);

                    input.tooltip({
                        placement: "right",
                        trigger: "manual"
                    });

                    input.tooltip("_fixTitle");
                    input.tooltip("show");
                    input.addClass("error");
                }

                return false;
            });

            input.keyup(function(event) {
                try {
                    checkInput();
                    input.tooltip("hide");
                    input.removeClass("error");
                } catch (error) {
                    input.attr("title", error);

                    input.tooltip({
                        placement: "right",
                        trigger: "manual"
                    });

                    input.tooltip("_fixTitle");
                    input.tooltip("show");
                    input.addClass("error");
                }

                if (event.keyCode === 27) {
                    restore();
                }
            });

            input.click(function(event) {
                event.stopPropagation();
                event.preventDefault();
            });

            input.blur(function() {
                if (input.hasClass("error")) {
                    restore();
                } else {
                    form.trigger("submit");
                }
            });
        },

        createFile: function(name, options) {
            const self = this;
            const deferred = $.Deferred();
            const promise = deferred.promise();
            OCA.Files.Files.isFileNameValid(name);

            if (this.lastAction) {
                this.lastAction();
            }

            name = this.getUniqueName(name);
            const targetPath = this.getCurrentDirectory() + "/" + name;

            self.filesClient.putFileContents(targetPath, " ", {
                contentType: "text/plain",
                overwrite: true
            }).done(function() {
                options = _.extend({
                    scrollTo: true
                }, options || {});

                self.addAndFetchFileInfo(targetPath, "", options).then(function(status, data) {
                    deferred.resolve(status, data);
                }, function() {
                    OC.Notification.show(t("files", "Could not create file \"{file}\"", {
                        file: name
                    }), {
                        type: "error"
                    });
                });
            }).fail(function(status) {
                if (status === 412) {
                    OC.Notification.show(t("files", "Could not create file \"{file}\" because it already exists", {
                        file: name
                    }), {
                        type: "error"
                    });
                } else {
                    OC.Notification.show(t("files", "Could not create file \"{file}\"", {
                        file: name
                    }), {
                        type: "error"
                    });
                }

                deferred.reject(status);
            });

            return promise;
        },

        createDirectory: function(name) {
            const self = this;
            const deferred = $.Deferred();
            const promise = deferred.promise();
            OCA.Files.Files.isFileNameValid(name);

            if (this.lastAction) {
                this.lastAction();
            }

            name = this.getUniqueName(name);
            const targetPath = this.getCurrentDirectory() + "/" + name;

            this.filesClient.createDirectory(targetPath).done(function() {
                self.addAndFetchFileInfo(targetPath, "", {
                    scrollTo: true
                }).then(function(status, data) {
                    deferred.resolve(status, data);
                }, function() {
                    OC.Notification.show(t("files", "Could not create folder \"{dir}\"", {
                        dir: name
                    }), {
                        type: "error"
                    });
                });
            }).fail(function(createStatus) {
                if (createStatus === 405) {
                    self.addAndFetchFileInfo(targetPath, "", {
                        scrollTo: true
                    }).done(function(status, data) {
                        OC.Notification.show(
                            t("files", "Could not create folder \"{dir}\" because it already exists", {
                                dir: name
                            }),
                            {
                                type: "error"
                            }
                        );

                        deferred.reject(createStatus, data);
                    }).fail(function() {
                        OC.Notification.show(t("files", "Could not create folder \"{dir}\"", {
                            dir: name
                        }), {
                            type: "error"
                        });

                        deferred.reject(status);
                    });
                } else {
                    OC.Notification.show(t("files", "Could not create folder \"{dir}\"", {
                        dir: name
                    }), {
                        type: "error"
                    });

                    deferred.reject(createStatus);
                }
            });

            return promise;
        },

        addAndFetchFileInfo: function(fileName, dir, options) {
            const self = this;
            const deferred = $.Deferred();

            if (_.isUndefined(dir)) {
                dir = this.getCurrentDirectory();
            } else {
                dir = dir || "/";
            }

            const targetPath = OC.joinPaths(dir, fileName);

            if ((OC.dirname(targetPath) || "/") !== this.getCurrentDirectory()) {
                deferred.resolve();
                return deferred.promise();
            }

            const addOptions = _.extend({
                animate: true,
                scrollTo: false
            }, options || {});

            this.filesClient.getFileInfo(targetPath, {
                properties: this._getWebdavProperties()
            }).then(function(status, data) {
                self.remove(data.name);
                self.add(data, addOptions);
                deferred.resolve(status, data);
            }).fail(function(status) {
                OCP.Toast.error(t("files", "Could not fetch file details \"{file}\"", {
                    file: fileName
                }));

                deferred.reject(status);
            });

            return deferred.promise();
        },

        inList: function(file) {
            return this.findFile(file);
        },

        showFileBusyState: function(files, state) {
            const self = this;

            if (!_.isArray(files) && !files.is) {
                files = [files];
            }

            if (_.isUndefined(state)) {
                state = true;
            }

            _.each(files, function(fileName) {
                let $tr;

                if (_.isString(fileName)) {
                    $tr = self.findFileEl(fileName);
                } else {
                    $tr = $(fileName);
                }

                const $thumbEl = $tr.find(".thumbnail");
                $tr.toggleClass("busy", state);

                if (state) {
                    $thumbEl.parent().addClass("icon-loading-small");
                } else {
                    $thumbEl.parent().removeClass("icon-loading-small");
                }
            });
        },

        do_delete: function(files, dir) {
            const self = this;

            if (files && files.substr) {
                files = [files];
            }

            if (!files) {
                files = _.pluck(this.files, "name");
            }

            if (this.lastAction) {
                this.lastAction();
            }

            dir = dir || this.getCurrentDirectory();

            const removeFunction = function(fileName) {
                const $tr = self.findFileEl(fileName);
                self.showFileBusyState($tr, true);

                return self.filesClient.remove(dir + "/" + fileName).done(function() {
                    if (OC.joinPaths(self.getCurrentDirectory(), "/") === OC.joinPaths(dir, "/")) {
                        self.remove(fileName);
                    }
                }).fail(function(status) {
                    if (status === 404) {
                        if (OC.joinPaths(self.getCurrentDirectory(), "/") === OC.joinPaths(dir, "/")) {
                            self.remove(fileName);
                        }
                    } else {
                        OC.Notification.show(t("files", "Error deleting file \"{fileName}\".", {
                            fileName: fileName
                        }), {
                            type: "error"
                        });
                    }
                }).always(function() {
                    self.showFileBusyState($tr, false);
                });
            };

            return this.reportOperationProgress(files, removeFunction).then(function() {
                self.updateStorageStatistics();
                self.updateStorageQuotas();
            });
        },

        _createSummary: function() {
            const $tr = $("<tr class=\"summary\"></tr>");

            if (this._allowSelection) {
                $tr.append("<td></td>");
            }

            this.$el.find("tfoot").append($tr);

            return new OCA.Files.FileSummary($tr, {
                config: this._filesConfig
            });
        },

        updateEmptyContent: function() {
            const permissions = this.getDirectoryPermissions();
            const isCreatable = (permissions & OC.PERMISSION_CREATE) !== 0;
            this.$el.find(".emptyfilelist.emptycontent").toggleClass("hidden", !this.isEmpty);
            this.$el.find(".emptyfilelist.emptycontent").toggleClass("hidden", !this.isEmpty);
            this.$el.find(".emptyfilelist.emptycontent .uploadmessage").toggleClass("hidden", !isCreatable || !this.isEmpty);
            this.$el.find(".files-filestable").toggleClass("hidden", this.isEmpty);
            this.$el.find(".files-filestable thead th").toggleClass("hidden", this.isEmpty);
        },

        showMask: function() {
            let $mask = this.$el.find(".mask");

            if ($mask.exists()) {
                return;
            }

            this.$table.addClass("hidden");
            this.$el.find(".emptyfilelist.emptycontent").addClass("hidden");
            $mask = $("<div class=\"mask transparent icon-loading\"></div>");
            this.$el.append($mask);
            $mask.removeClass("transparent");
        },

        hideMask: function() {
            this.$el.find(".mask").remove();
            this.$table.removeClass("hidden");
        },

        scrollTo: function(file) {
            if (!_.isArray(file)) {
                file = [file];
            }

            if (file.length === 1) {
                _.defer(function() {
                    this.showDetailsView(file[0]);
                }.bind(this));
            }

            this.highlightFiles(file, function($tr) {
                $tr.addClass("searchresult");

                $tr.one("hover", function() {
                    $tr.removeClass("searchresult");
                });
            });
        },

        filter: function(query) {
            this.setFilter("");
        },

        unfilter: function() {
            this.setFilter("");
        },

        setFilter: function(filter) {
            let total = 0;

            if (this._filter === filter) {
                return;
            }

            this._filter = filter;
            this.fileSummary.setFilter(filter, this.files);
            total = this.fileSummary.getTotal();

            if (!this.$el.find(".mask").exists()) {
                this.hideIrrelevantUIWhenNoFilesMatch();
            }

            let visibleCount = 0;
            filter = filter.toLowerCase();

            function filterRows(tr) {
                const $e = $(tr);

                if ($e.data("file").toString().toLowerCase().indexOf(filter) === -1) {
                    $e.addClass("hidden");
                } else {
                    visibleCount++;
                    $e.removeClass("hidden");
                }
            }

            let $trs = this.$fileList.find("tr");

            do {
                _.each($trs, filterRows);

                if (visibleCount < total) {
                    $trs = this._nextPage(false);
                }
            } while (visibleCount < total && $trs.length > 0);

            this.$container.trigger("scroll");
        },

        hideIrrelevantUIWhenNoFilesMatch: function() {
            if (this._filter && this.fileSummary.summary.totalDirs + this.fileSummary.summary.totalFiles === 0) {
                this.$el.find(".files-filestable thead th").addClass("hidden");
                this.$el.find(".emptyfilelist.emptycontent").addClass("hidden");
                $("#searchresults").addClass("filter-empty");
                $("#searchresults .emptycontent").addClass("emptycontent-search");

                if ($("#searchresults").length === 0 || $("#searchresults").hasClass("hidden")) {
                    let error;

                    if (this._filter.length > 2) {
                        error = t("files", "No search results in other folders for {tag}{filter}{endtag}", {
                            filter: this._filter
                        });
                    } else {
                        error = t("files", "Enter more than two characters to search in other folders");
                    }

                    this.$el.find(".nofilterresults").removeClass("hidden").find("p").html(error.replace("{tag}", "<strong>").replace("{endtag}", "</strong>"));
                }
            } else {
                $("#searchresults").removeClass("filter-empty");
                $("#searchresults .emptycontent").removeClass("emptycontent-search");
                this.$el.find(".files-filestable thead th").toggleClass("hidden", this.isEmpty);

                if (!this.$el.find(".mask").exists()) {
                    this.$el.find(".emptyfilelist.emptycontent").toggleClass("hidden", !this.isEmpty);
                }

                this.$el.find(".nofilterresults").addClass("hidden");
            }
        },

        getFilter: function(filter) {
            return this._filter;
        },

        updateSelectionSummary: function() {
            const summary = this._selectionSummary.summary;
            let selection;
            const showHidden = !!this._filesConfig.get("showhidden");

            if (summary.totalFiles === 0 && summary.totalDirs === 0) {
                this.$el.find(".column-name a.name>span:first").text(t("files", "Name"));
                this.$el.find(".column-size a>span:first").text(t("files", "Size"));
                this.$el.find(".column-mtime a>span:first").text(t("files", "Modified"));
                this.$el.find("table").removeClass("multiselect");
                this.$el.find(".selectedActions").addClass("hidden");
            } else {
                this.$el.find(".selectedActions").removeClass("hidden");
                this.$el.find(".column-size a>span:first").text(OC.Util.humanFileSize(summary.totalSize));
                const directoryInfo = n("files", "%n folder", "%n folders", summary.totalDirs);
                const fileInfo = n("files", "%n file", "%n files", summary.totalFiles);

                if (summary.totalDirs > 0 && summary.totalFiles > 0) {
                    const selectionVars = {
                        dirs: directoryInfo,
                        files: fileInfo
                    };

                    selection = t("files", "{dirs} and {files}", selectionVars);
                } else if (summary.totalDirs > 0) {
                    selection = directoryInfo;
                } else {
                    selection = fileInfo;
                }

                if (!showHidden && summary.totalHidden > 0) {
                    const hiddenInfo = n("files", "including %n hidden", "including %n hidden", summary.totalHidden);
                    selection += " (" + hiddenInfo + ")";
                }

                this.$el.find(".column-name a.name>span:first").text(selection);
                this.$el.find(".column-mtime a>span:first").text("");
                this.$el.find("table").addClass("multiselect");

                if (this.fileMultiSelectMenu) {
                    this.fileMultiSelectMenu.toggleItemVisibility("download", this.isSelectedDownloadable());
                    this.fileMultiSelectMenu.toggleItemVisibility("delete", this.isSelectedDeletable());
                    this.fileMultiSelectMenu.toggleItemVisibility("copyMove", this.isSelectedCopiable());

                    if (this.isSelectedCopiable()) {
                        if (this.isSelectedMovable()) {
                            this.fileMultiSelectMenu.updateItemText("copyMove", t("files", "Move or copy"));
                        } else {
                            this.fileMultiSelectMenu.updateItemText("copyMove", t("files", "Copy"));
                        }
                    } else {
                        this.fileMultiSelectMenu.toggleItemVisibility("copyMove", false);
                    }
                }
            }
        },

        isSelectedCopiable: function() {
            return _.reduce(this.getSelectedFiles(), function(copiable, file) {
                const requiredPermission = $("#isPublic").val() ? OC.PERMISSION_UPDATE : OC.PERMISSION_READ;
                return copiable && file.permissions & requiredPermission;
            }, true);
        },

        isSelectedMovable: function() {
            return _.reduce(this.getSelectedFiles(), function(movable, file) {
                return movable && file.permissions & OC.PERMISSION_UPDATE;
            }, true);
        },

        isSelectedDownloadable: function() {
            return _.reduce(this.getSelectedFiles(), function(downloadable, file) {
                return downloadable && file.permissions & OC.PERMISSION_READ;
            }, true);
        },

        isSelectedDeletable: function() {
            return _.reduce(this.getSelectedFiles(), function(deletable, file) {
                return deletable && file.permissions & OC.PERMISSION_DELETE;
            }, true);
        },

        isAllSelected: function() {
            const checkbox = this.$el.find(".select-all");
            const checked = checkbox.prop("checked");
            const indeterminate = checkbox.prop("indeterminate");
            return checked && !indeterminate;
        },

        getSelectedFiles: function() {
            return _.values(this._selectedFiles);
        },

        getUniqueName: function(name) {
            if (this.findFileEl(name).exists()) {
                let numMatch;
                const parts = name.split(".");
                let extension = "";

                if (parts.length > 1) {
                    extension = parts.pop();
                }

                let base = parts.join(".");
                numMatch = base.match(/\((\d+)\)/);
                let num = 2;

                if (numMatch && numMatch.length > 0) {
                    num = parseInt(numMatch[numMatch.length - 1], 10) + 1;
                    base = base.split("(");
                    base.pop();
                    base = $.trim(base.join("("));
                }

                name = base + " (" + num + ")";

                if (extension) {
                    name = name + "." + extension;
                }

                return this.getUniqueName(name);
            }

            return name;
        },

        _showPermissionDeniedNotification: function() {
            const message = t("files", "You do not have permission to upload or create files here");

            OC.Notification.show(message, {
                type: "error"
            });
        },

        setupUploadEvents: function(uploader) {
            const self = this;
            self._uploads = {};
            uploader.on("resized", this._onResize);

            uploader.on("drop", function(e, data) {
                self._uploader.log("filelist handle fileuploaddrop", e, data);

                if (self.$el.hasClass("hidden")) {
                    e.preventDefault();
                    return false;
                }

                let dropTarget = $(e.delegatedEvent.target);

                if (dropTarget.length && !self.$el.is(dropTarget) && !self.$el.has(dropTarget).length && !dropTarget.is(self.$container) && !self.$el.parent().is(dropTarget)) {
                    e.preventDefault();
                    return false;
                }

                dropTarget = dropTarget.closest("tr, .crumb");

                if (dropTarget && (dropTarget.data("type") === "dir" || dropTarget.hasClass("crumb"))) {
                    data.context = dropTarget;
                    const permissions = dropTarget.data("permissions");

                    if (!_.isUndefined(permissions) && (permissions & OC.PERMISSION_CREATE) === 0) {
                        self._showPermissionDeniedNotification();
                        return false;
                    }

                    let dir = dropTarget.data("file");

                    if (dir) {
                        let parentDir = self.getCurrentDirectory();

                        if (parentDir[parentDir.length - 1] !== "/") {
                            parentDir += "/";
                        }

                        dir = parentDir + dir;
                    } else {
                        dir = dropTarget.data("dir") || "/";
                    }

                    data.targetDir = dir;
                } else {
                    const isCreatable = (self.getDirectoryPermissions() & OC.PERMISSION_CREATE) !== 0;

                    if (!isCreatable) {
                        self._showPermissionDeniedNotification();
                        e.stopPropagation();
                        return false;
                    }

                    data.targetDir = self.getCurrentDirectory();
                }
            });

            uploader.on("add", function(e, data) {
                self._uploader.log("filelist handle fileuploadadd", e, data);

                if (data.context && data.context.data("type") === "dir") {
                    const uploadText = data.context.find(".uploadtext");
                    let currentUploads = parseInt(uploadText.attr("currentUploads"), 10);
                    currentUploads += 1;
                    uploadText.attr("currentUploads", currentUploads);
                    const translatedText = n("files", "Uploading %n file", "Uploading %n files", currentUploads);

                    if (currentUploads === 1) {
                        self.showFileBusyState(uploadText.closest("tr"), true);
                        uploadText.text(translatedText);
                        uploadText.show();
                    } else {
                        uploadText.text(translatedText);
                    }
                }

                if (!data.targetDir) {
                    data.targetDir = self.getCurrentDirectory();
                }
            });

            uploader.on("done", function(e, upload) {
                const data = upload.data;
