function runCommand(command, args, done) {
    if (typeof args === "function") {
        done = args;
        args = "";
    }

    exec("p4 " + command + " " + (args || ""), function(err, stdOut, stdErr) {
        if (err)
            return done(err);

        if (stdErr)
            return done(new Error(stdErr));

        done(null, stdOut);
    });
}

function runCommand(command, args, done) {
    if (typeof args === "function") {
        done = args;
        args = "";
    }

    if (!Array.isArray(args)) {
        args = [args];
    }

    args.unshift(command);
    const child = spawn("p4", args);
    let stdOutBuf = "";
    let stdErrBuf = "";
    child.stdout.on("data", data => (stdOutBuf += data));
    child.stderr.on("data", data => (stdErrBuf += data));

    child.on("exit", code => {
        if (code !== 0) {
            return done(new Error(`p4 subcommand exited with return code ${code}`));
        }

        if (stdErrBuf.length > 0) {
            return done(new Error(stdErrBuf));
        }

        done(null, stdOutBuf);
    });
}

