(function(exports) {
    exports.isSpintax = function(text) {
        return text.match(/{.*(\|.*)+}/) !== null;
    };

    exports.findSpintax = function(text) {
        return text.match(/{([^{}]+?)}/);
    };

    exports.unspin = function(text) {
        let spin;
        let options;
        let choice;
        const originalText = text;
        let unspinCount = 0;

        while (exports.isSpintax(text)) {
            if (unspinCount >= 1000) {
                throw new Error("Unable unspin text after 1000 iterations (" + originalText + ")");
            }

            spin = exports.findSpintax(text);
            options = spin[1].split("|");
            choice = options[Math.floor(Math.random() * options.length)];
            text = text.replace(spin[0], choice);
            unspinCount++;
        }

        return text;
    };

    exports.count = function(text) {
        let spin;
        let options;
        let num;
        let totals;
        let total = 0;
        let i;
        const reFind = /%%%\d+%%%/g;
        const reParse = /%%%(\d+)%%%/;
        const ps = "N";
        const pm = "%%%" + ps + "%%%";
        const originalText = text;
        let unspinCount = 0;

        while (exports.isSpintax(text)) {
            if (unspinCount >= 1000) {
                throw new Error("Unable unspin text after 1000 iterations (" + originalText + ")");
            }

            spin = exports.findSpintax(text);
            options = spin[1].split("|");
            num = 0;

            for (i = 0; i < options.length; i++) {
                if (options[i].match(reFind)) {
                    num += parseInt(options[i].match(reParse)[1]) || 1;
                } else {
                    num += 1;
                }
            }

            text = text.replace(spin[0], pm.replace(ps, num.toString()));
            unspinCount++;
        }

        if (text.match(reFind)) {
            totals = text.match(reFind);
            total = 1;

            for (i = 0; i < totals.length; i++) {
                total *= parseInt(totals[i].match(reParse)[1]) || 1;
            }
        }

        return total;
    };

    exports.validate = function(text) {
        text = exports.unspin(text);
        return text.match(/({[^}]*\|)|(\|[^{]*})/) === null;
    };
})

function start(config) {
    let host = conf.constant.host;

    if (config)
        conf.serv = config;

    function onRequest(request, response) {
        const frontUrl = "";

        if (request.url === "/favicon.ico")
            return;

        for (const key in conf.serv) {
            if (request.headers.host.indexOf(key) !== -1) {
                host = conf.serv[key];
            }
        }

        const nowTemp = host.frondend + (request.url.replace("/", "") || host.baseTemp);
        const httpHead = header(nowTemp);
        conf.app = conf.getApp(host.backend);

        if (!host) {
            error(response);
            return;
        }

        const defaultTemp = function() {
            fs.readFile(host.frondend + host.baseTemp, function(err, file) {
                if (err) {
                    error(response, err);
                    return;
                }

                responseTemp(response, httpHead, file);
            });
        };

        const send = function(res) {
            if (res) {
                if (res === "error") {
                    error(response, "Route config error!");
                    return;
                }

                if (res.html) {
                    response.writeHead(res.status, {
                        "Content-Type": "text/html;charset:utf-8"
                    });

                    response.write(res.html);
                    response.end();
                    return;
                } else if (res.status === 302) {
                    response.writeHead(res.status, {
                        "Content-Type": "text/html;charset:utf-8",
                        Location: res.url
                    });

                    response.end();
                    return;
                } else if (res.data) {
                    response.writeHead(res.status, {
                        "Content-Type": "application/json"
                    });

                    response.write(JSON.stringify(res));
                    response.end();
                    return;
                } else {
                    error(response, "Data type error!");
                }
            } else {
                fs.exists(nowTemp, function(exists) {
                    if (!exists) {
                        defaultTemp();
                    } else {
                        fs.readFile(nowTemp, function(err, file) {
                            if (err) {
                                defaultTemp();
                            } else {
                                responseTemp(response, httpHead, file);
                            }
                        });
                    }
                });
            }
        };

        route(conf.app.url, request, send);
    }

    http.createServer(onRequest).listen(conf.constant.port);
    console.log("server running at " + conf.constant.port);
}

