function resolveMetadataRecord(owner: object, context: Context, useMetaFromContext: boolean): MetadataRecord {
    if (useMetaFromContext) {
        return context.metadata as MetadataRecord;
    }

    let metadata: MetadataRecord = registry.get(owner) ?? {};

    if (Reflect.has(owner, METADATA)) {
        metadata = Object.assign(metadata, owner[METADATA]);
    }

    return metadata;
}

function resolveMetadataRecord(owner: object, context: Context, useMetaFromContext: boolean): MetadataRecord {
    if (useMetaFromContext) {
        return context.metadata as MetadataRecord;
    }

    let metadata: MetadataRecord = registry.get(owner) ?? Object.create(null);

    if (Reflect.has(owner, METADATA)) {
        metadata = Object.assign(metadata, owner[METADATA]);
    }

    return metadata;
}

function replace(
    str: string,
    replacement: string | ((emoji: Emoji) => string) = "",
    trim = false
): string {
    if (!str)
        return "";

    const replace = typeof replacement === "function" ? replacement : () => {
        return replacement;
    };

    const match = str.match(reUnicode) ?? [];

    const result = match.map((s, i) => {
        const emoji = byCode[stripNSB(s)];

        if (emoji && trim && match[i + 1] === " ") {
            match[i + 1] = "";
        }

        return emoji ? replace(emoji) : s;
    }).join("");

    return trim ? result.replace(reTrimSpace, "") : result;
}

