    const testButton = document.getElementById("test-connection");
    const testConnEnabled = testableConnections.includes(connectionType);

    if (testConnEnabled) {
        $(testButton).prop("disabled", false).removeAttr("title");
    } else {
        $(testButton).prop("disabled", true).attr(
            "title",
            "This connection type does not currently support testing via " + "Airflow REST API."
        );
    }
}

