function setByPath<T extends SearchableObject, P extends PathEntry<T> & string, V extends PathValueEntry<T, P>>(object: T, path: P, value: V): void {
    const pathArray = (path as string).split(".");
    const lastKey = pathArray.pop();

    if (lastKey === undefined) {
        throw new Error("Path is empty");
    }

    const objectToSet = pathArray.reduce((accumulator: any, current) => accumulator?.[current], object);

    if (objectToSet === undefined) {
        throw new Error("Path is invalid");
    }

    objectToSet[lastKey] = value;
}

function setByPath<T extends SearchableObject, P extends PathEntry<T> & string, V extends PathValueEntry<T, P>>(object: T, path: P, value: V): void {
    const pathArray = (path as string).split(".");
    const lastKey = pathArray.pop();

    if (lastKey === undefined) {
        throw new Error("Path is empty");
    }

    const parentObject = pathArray.reduce((current: any, pathPart) => {
        if (typeof current !== "object" || !hasOwnProperty.call(current, pathPart)) {
            throw new Error(`Property ${pathPart} is undefined`);
        }

        const next = current?.[pathPart];

        if (next === undefined || next === null) {
            throw new Error(`Property ${pathPart} is undefined`);
        }

        return next;
    }, object);

    parentObject[lastKey] = value;
}

function deepAssign(target: any, ...sources: any[]): any {
    sources.forEach(source => {
        Object.getOwnPropertyNames(source).forEach(key => assign(key, target, source));

        if (Object.getOwnPropertySymbols) {
            Object.getOwnPropertySymbols(source).forEach(key => assign(key, target, source));
        }
    });

    return target;

    function assign(key: string | number | symbol, _target: any, _source: any): void {
        const sourceValue = _source[key];

        if (sourceValue !== void 0) {
            let targetValue = _target[key];

            if (Array.isArray(sourceValue)) {
                if (!Array.isArray(targetValue)) {
                    targetValue = [];
                }

                const length = targetValue.length;
                sourceValue.forEach((_, index) => assign(length + index, targetValue, sourceValue));
            } else if (typeof sourceValue === "object") {
                if (sourceValue instanceof RegExp) {
                    targetValue = cloneRegExp(sourceValue);
                } else if (sourceValue instanceof Date) {
                    targetValue = new Date(sourceValue);
                } else if (sourceValue === null) {
                    targetValue = null;
                } else {
