async (
    {
        key,
        value,
        writeOutputFiles,
        outputDir,
        json = false,
        shouldEscape = false,
        safeOutput = false
    }: {
        key: string;
        value: string | string[] | boolean;
        writeOutputFiles: boolean;
        outputDir: string;
        json?: boolean;
        shouldEscape?: boolean;
        safeOutput?: boolean;
    }
): Promise<void> => {
    let cleanedValue;

    if (json) {
        cleanedValue = jsonOutput({
            value,
            shouldEscape
        });
    } else {
        cleanedValue = value.toString().trim();
    }

    if (safeOutput) {
        cleanedValue = cleanedValue.replace(/[^\x20-\x7E]|[:*?"<>|;`$()&!]/g, "\\$&");
    }

    core.setOutput(key, cleanedValue);

    if (writeOutputFiles) {
        const extension = json ? "json" : "txt";
        const outputFilePath = path.join(outputDir, `${key}.${extension}`);

        if (!(await exists(outputDir))) {
            await fs.mkdir(outputDir, {
                recursive: true
            });
        }

        await fs.writeFile(outputFilePath, cleanedValue.replace(/\\"/g, "\""));
    }
}

