}

function api_factory(
    fetch_implementation: typeof fetch,
    EventSource_factory: (url: URL) => EventSource
): Client {
    return {
        post_data,
        upload_files,
        client,
        handle_blob
    };

    async function post_data(url: string, body: unknown, token?: `hf_${string}`): Promise<[PostResponse, number]> {
        const headers: {
            Authorization?: string;
            "Content-Type": "application/json";
        } = {
            "Content-Type": "application/json"
        };

        if (token) {
            headers.Authorization = `Bearer ${token}`;
        }

        try {
            var response = await fetch_implementation(url, {
                method: "POST",
                body: JSON.stringify(body),
                headers
            });
        } catch (e) {
            return [{
                error: BROKEN_CONNECTION_MSG
            }, 500];
        }

        const output: PostResponse = await response.json();
        return [output, response.status];
    }

    async function upload_files(
        root: string,
        files: (Blob | File)[],
        token?: `hf_${string}`,
        upload_id?: string
    ): Promise<UploadResponse> {
        const headers: {
            Authorization?: string;
        } = {};

        if (token) {
            headers.Authorization = `Bearer ${token}`;
        }

        const chunkSize = 1000;
        const uploadResponses = [];

        for (let i = 0; i < files.length; i += chunkSize) {
            const chunk = files.slice(i, i + chunkSize);
            const formData = new FormData();

            chunk.forEach(file => {
                formData.append("files", file);
            });

            try {
                const upload_url = upload_id ? `${root}/upload?upload_id=${upload_id}` : `${root}/upload`;

                var response = await fetch_implementation(upload_url, {
                    method: "POST",
                    body: formData,
                    headers
                });
            } catch (e) {
                return {
                    error: BROKEN_CONNECTION_MSG
                };
            }

            const output: UploadResponse["files"] = await response.json();
            uploadResponses.push(...output);
        }

        return {
            files: uploadResponses
        };
    }

    async function client(
        app_reference: string,
        options: {
            hf_token?: `hf_${string}`;
            status_callback?: SpaceStatusCallback;
            normalise_files?: boolean;
        } = {
            normalise_files: true
        }
    ): Promise<client_return> {
        return new Promise(async res => {
            const {
                status_callback,
                hf_token,
                normalise_files
            } = options;

            const return_obj = {
                predict,
                submit,
                view_api,
                component_server
            };

            const transform_files = normalise_files ?? true;

            if ((typeof window === "undefined" || !("WebSocket" in window)) && !global.Websocket) {
                const ws = await import("ws");
                NodeBlob = (await import("node:buffer")).Blob;
                global.WebSocket = ws.WebSocket;
            }

            const {
                ws_protocol,
                http_protocol,
                host,
                space_id
            } = await process_endpoint(app_reference, hf_token);

            const session_hash = Math.random().toString(36).substring(2);
            const last_status: Record<string, Status["stage"]> = {};
            let config: Config;
            let api_map: Record<string, number> = {};
            let jwt: false | string = false;

            if (hf_token && space_id) {
                jwt = await get_jwt(space_id, hf_token);
            }

            async function config_success(_config: Config): Promise<client_return> {
                config = _config;
                api_map = map_names_to_ids(_config?.dependencies || []);

                if (config.auth_required) {
                    return {
                        config,
                        ...return_obj
                    };
                }

                try {
                    api = await view_api(config);
                } catch (e) {
                    console.error(`Could not get api details: ${e.message}`);
                }

                return {
                    config,
                    ...return_obj
                };
            }

            let api: ApiInfo<JsApiData>;

            async function handle_space_sucess(status: SpaceStatus): Promise<void> {
                if (status_callback)
                    status_callback(status);

                if (status.status === "running") try {
                    config = await resolve_config(fetch_implementation, `${http_protocol}//${host}`, hf_token);
                    const _config = await config_success(config);
                    res(_config);
                } catch (e) {
                    console.error(e);

                    if (status_callback) {
                        status_callback({
                            status: "error",
                            message: "Could not load this space.",
                            load_status: "error",
                            detail: "NOT_FOUND"
                        });
                    }
                }
            }

            try {
                config = await resolve_config(fetch_implementation, `${http_protocol}//${host}`, hf_token);
                const _config = await config_success(config);
                res(_config);
            } catch (e) {
                console.error(e);

                if (space_id) {
                    check_space_status(
                        space_id,
                        RE_SPACE_NAME.test(space_id) ? "space_name" : "subdomain",
                        handle_space_sucess
                    );
                } else {
                    if (status_callback) status_callback({
                        status: "error",
                        message: "Could not load this space.",
                        load_status: "error",
                        detail: "NOT_FOUND"
                    });
                }
            }

            function predict(endpoint: string, data: unknown[], event_data?: unknown): Promise<unknown> {
                let data_returned = false;
                let status_complete = false;
                let dependency;

                if (typeof endpoint === "number") {
                    dependency = config.dependencies[endpoint];
                } else {
                    const trimmed_endpoint = endpoint.replace(/^\//, "");
                    dependency = config.dependencies[api_map[trimmed_endpoint]];
                }

                if (dependency.types.continuous) {
                    throw new Error(
                        "Cannot call predict on this function as it may run forever. Use submit instead"
                    );
                }

                return new Promise((res, rej) => {
                    const app = submit(endpoint, data, event_data);
                    let result;

                    app.on("data", d => {
                        if (status_complete) {
                            app.destroy();
                            res(d);
                        }

                        data_returned = true;
                        result = d;
                    }).on("status", status => {
                        if (status.stage === "error")
                            rej(status);

                        if (status.stage === "complete") {
                            status_complete = true;

                            if (data_returned) {
                                app.destroy();
                                res(result);
                            }
                        }
                    });
                });
            }

            function submit(
                endpoint: string | number,
                data: unknown[],
                event_data?: unknown,
                trigger_id: number | null = null
            ): SubmitReturn {
                let fn_index: number;
                let api_info;

                if (typeof endpoint === "number") {
                    fn_index = endpoint;
                    api_info = api.unnamed_endpoints[fn_index];
                } else {
                    const trimmed_endpoint = endpoint.replace(/^\//, "");
                    fn_index = api_map[trimmed_endpoint];
                    api_info = api.named_endpoints[endpoint.trim()];
                }

                if (typeof fn_index !== "number") {
                    throw new Error(
                        "There is no endpoint matching that name of fn_index matching that number."
                    );
                }

                let websocket: WebSocket;
                let eventSource: EventSource;
                const protocol = config.protocol ?? "sse";
                const _endpoint = typeof endpoint === "number" ? "/predict" : endpoint;
                let payload: Payload;
                let event_id: string | null = null;
                let complete: false | Record<string, any> = false;
                const listener_map: ListenerMap<EventType> = {};
                let url_params = "";

                if (typeof window !== "undefined") {
                    url_params = new URLSearchParams(window.location.search).toString();
                }

                handle_blob(
                    `${http_protocol}//${resolve_root(host, config.path, true)}`,
                    data,
                    api_info,
                    hf_token
                ).then(_payload => {
                    payload = {
                        data: _payload || [],
                        event_data,
                        fn_index,
                        trigger_id
                    };

                    if (skip_queue(fn_index, config)) {
                        fire_event({
                            type: "status",
                            endpoint: _endpoint,
                            stage: "pending",
                            queue: false,
                            fn_index,
                            time: new Date()
                        });

                        post_data(
                            `${http_protocol}//${resolve_root(host, config.path, true)}/run${_endpoint.startsWith("/") ? _endpoint : `/${_endpoint}`}${url_params ? "?" + url_params : ""}`,
                            {
                                ...payload,
                                session_hash
                            },
                            hf_token
                        ).then(([output, status_code]) => {
                            const data = transform_files ? transform_output(output.data, api_info, config.root, config.root_url) : output.data;

                            if (status_code == 200) {
                                fire_event({
                                    type: "data",
                                    endpoint: _endpoint,
                                    fn_index,
                                    data: data,
                                    time: new Date()
                                });

                                fire_event({
                                    type: "status",
                                    endpoint: _endpoint,
                                    fn_index,
                                    stage: "complete",
                                    eta: output.average_duration,
                                    queue: false,
                                    time: new Date()
                                });
                            } else {
                                fire_event({
                                    type: "status",
                                    stage: "error",
                                    endpoint: _endpoint,
                                    fn_index,
                                    message: output.error,
                                    queue: false,
                                    time: new Date()
                                });
                            }
                        }).catch(e => {
                            fire_event({
                                type: "status",
                                stage: "error",
                                message: e.message,
                                endpoint: _endpoint,
                                fn_index,
                                queue: false,
                                time: new Date()
                            });
                        });
                    } else if (protocol == "ws") {
                        fire_event({
                            type: "status",
                            stage: "pending",
                            queue: true,
                            endpoint: _endpoint,
                            fn_index,
                            time: new Date()
                        });

                        const url = new URL(`${ws_protocol}://${resolve_root(host, config.path, true)}
                            /queue/join${url_params ? "?" + url_params : ""}`);

                        if (jwt) {
                            url.searchParams.set("__sign", jwt);
                        }

                        websocket = new WebSocket(url);

                        websocket.onclose = evt => {
                            if (!evt.wasClean) {
                                fire_event({
                                    type: "status",
                                    stage: "error",
                                    broken: true,
                                    message: BROKEN_CONNECTION_MSG,
                                    queue: true,
                                    endpoint: _endpoint,
                                    fn_index,
                                    time: new Date()
                                });
                            }
                        };

                        websocket.onmessage = function(event) {
                            const _data = JSON.parse(event.data);

                            const {
                                type,
                                status,
                                data
                            } = handle_message(_data, last_status[fn_index]);

                            if (type === "update" && status && !complete) {
                                fire_event({
                                    type: "status",
                                    endpoint: _endpoint,
                                    fn_index,
                                    time: new Date(),
                                    ...status
                                });

                                if (status.stage === "error") {
                                    websocket.close();
                                }
                            } else if (type === "hash") {
                                websocket.send(JSON.stringify({
                                    fn_index,
                                    session_hash
                                }));

                                return;
                            } else if (type === "data") {
                                websocket.send(JSON.stringify({
                                    ...payload,
                                    session_hash
                                }));
                            } else if (type === "complete") {
                                complete = status;
                            } else if (type === "log") {
                                fire_event({
                                    type: "log",
                                    log: data.log,
                                    level: data.level,
                                    endpoint: _endpoint,
                                    fn_index
                                });
                            } else if (type === "generating") {
                                fire_event({
                                    type: "status",
                                    time: new Date(),
                                    ...status,
                                    stage: status?.stage!,
                                    queue: true,
                                    endpoint: _endpoint,
                                    fn_index
                                });
                            }

                            if (data) {
                                fire_event({
                                    type: "data",
                                    time: new Date(),
                                    data: transform_files ? transform_output(data.data, api_info, config.root, config.root_url) : data.data,
                                    endpoint: _endpoint,
                                    fn_index
                                });

                                if (complete) {
                                    fire_event({
                                        type: "status",
                                        time: new Date(),
                                        ...complete,
                                        stage: status?.stage!,
                                        queue: true,
                                        endpoint: _endpoint,
                                        fn_index
                                    });

                                    websocket.close();
                                }
                            }
                        };

                        if (semiver(config.version || "2.0.0", "3.6") < 0) {
                            addEventListener("open", () => websocket.send(JSON.stringify({
                                hash: session_hash
                            })));
                        }
                    } else {
                        fire_event({
                            type: "status",
                            stage: "pending",
                            queue: true,
                            endpoint: _endpoint,
                            fn_index,
                            time: new Date()
                        });

                        const params = new URLSearchParams({
                            fn_index: fn_index.toString(),
                            session_hash: session_hash
                        }).toString();

                        const url = new URL(
                            `${http_protocol}//${resolve_root(host, config.path, true)}/queue/join?${url_params ? url_params + "&" : ""}${params}`
                        );

                        eventSource = EventSource_factory(url);

                        eventSource.onmessage = async function(event) {
                            const _data = JSON.parse(event.data);

                            const {
                                type,
                                status,
                                data
                            } = handle_message(_data, last_status[fn_index]);

                            if (type === "update" && status && !complete) {
                                fire_event({
                                    type: "status",
                                    endpoint: _endpoint,
                                    fn_index,
                                    time: new Date(),
                                    ...status
                                });

                                if (status.stage === "error") {
                                    eventSource.close();
                                }
                            } else if (type === "data") {
                                event_id = _data.event_id as string;

                                const [_, status] = await post_data(`${http_protocol}//${resolve_root(host, config.path, true)}/queue/data`, {
                                    ...payload,
                                    session_hash,
                                    event_id
                                }, hf_token);

                                if (status !== 200) {
                                    fire_event({
                                        type: "status",
                                        stage: "error",
                                        message: BROKEN_CONNECTION_MSG,
                                        queue: true,
                                        endpoint: _endpoint,
                                        fn_index,
                                        time: new Date()
                                    });

                                    eventSource.close();
                                }
                            } else if (type === "complete") {
                                complete = status;
                            } else if (type === "log") {
                                fire_event({
                                    type: "log",
                                    log: data.log,
                                    level: data.level,
                                    endpoint: _endpoint,
                                    fn_index
                                });
                            } else if (type === "generating") {
                                fire_event({
                                    type: "status",
                                    time: new Date(),
                                    ...status,
                                    stage: status?.stage!,
                                    queue: true,
                                    endpoint: _endpoint,
                                    fn_index
                                });
                            }

                            if (data) {
                                fire_event({
                                    type: "data",
                                    time: new Date(),
                                    data: transform_files ? transform_output(data.data, api_info, config.root, config.root_url) : data.data,
                                    endpoint: _endpoint,
                                    fn_index
                                });

                                if (complete) {
                                    fire_event({
                                        type: "status",
                                        time: new Date(),
                                        ...complete,
                                        stage: status?.stage!,
                                        queue: true,
                                        endpoint: _endpoint,
                                        fn_index
                                    });

                                    eventSource.close();
                                }
                            }
                        };
                    }
                });

                function fire_event<K extends EventType>(event: Event<K>): void {
                    const narrowed_listener_map: ListenerMap<K> = listener_map;
                    const listeners = narrowed_listener_map[event.type] || [];
                    listeners?.forEach(l => l(event));
                }

                function on<K extends EventType>(eventType: K, listener: EventListener<K>): SubmitReturn {
                    const narrowed_listener_map: ListenerMap<K> = listener_map;
                    const listeners = narrowed_listener_map[eventType] || [];
                    narrowed_listener_map[eventType] = listeners;
                    listeners?.push(listener);

                    return {
                        on,
                        off,
                        cancel,
                        destroy
                    };
                }

                function off<K extends EventType>(eventType: K, listener: EventListener<K>): SubmitReturn {
                    const narrowed_listener_map: ListenerMap<K> = listener_map;
                    let listeners = narrowed_listener_map[eventType] || [];
                    listeners = listeners?.filter(l => l !== listener);
                    narrowed_listener_map[eventType] = listeners;

                    return {
                        on,
                        off,
                        cancel,
                        destroy
                    };
                }

                async function cancel(): Promise<void> {
                    const _status: Status = {
                        stage: "complete",
                        queue: false,
                        time: new Date()
                    };

                    complete = _status;

                    fire_event({
                        ..._status,
                        type: "status",
                        endpoint: _endpoint,
                        fn_index: fn_index
                    });

                    let cancel_request = {};

                    if (protocol === "ws") {
                        if (websocket && websocket.readyState === 0) {
                            websocket.addEventListener("open", () => {
                                websocket.close();
                            });
                        } else {
                            websocket.close();
                        }

                        cancel_request = {
                            fn_index,
                            session_hash
                        };
                    } else {
                        eventSource.close();

                        cancel_request = {
                            event_id
                        };
                    }

                    try {
                        await fetch_implementation(`${http_protocol}//${resolve_root(host, config.path, true)}/reset`, {
                            headers: {
                                "Content-Type": "application/json"
                            },

                            method: "POST",
                            body: JSON.stringify(cancel_request)
                        });
                    } catch (e) {
                        console.warn(
                            "The `/reset` endpoint could not be called. Subsequent endpoint results may be unreliable."
                        );
                    }
                }

                function destroy(): void {
                    for (const event_type in listener_map) {
                        listener_map[event_type as "data" | "status"].forEach(fn => {
                            off(event_type as "data" | "status", fn);
                        });
                    }
                }

                return {
                    on,
                    off,
                    cancel,
                    destroy
                };
            }

            async function component_server(component_id: number, fn_name: string, data: unknown[]): Promise<any> {
                const headers: {
                    Authorization?: string;
                    "Content-Type": "application/json";
                } = {
                    "Content-Type": "application/json"
                };

                if (hf_token) {
                    headers.Authorization = `Bearer ${hf_token}`;
                }

                let root_url: string;
                const component = config.components.find(comp => comp.id === component_id);

                if (component?.props?.root_url) {
                    root_url = component.props.root_url;
                } else {
                    root_url = `${http_protocol}//${resolve_root(host, config.path, true)}/`;
                }

                const response = await fetch_implementation(`${root_url}component_server/`, {
                    method: "POST",

                    body: JSON.stringify({
                        data: data,
                        component_id: component_id,
                        fn_name: fn_name,
                        session_hash: session_hash
                    }),

                    headers
                });

                if (!response.ok) {
                    throw new Error("Could not connect to component server: " + response.statusText);
                }

                const output = await response.json();
                return output;
            }

            async function view_api(config?: Config): Promise<ApiInfo<JsApiData>> {
                if (api)
                    return api;

                const headers: {
                    Authorization?: string;
                    "Content-Type": "application/json";
                } = {
                    "Content-Type": "application/json"
                };

                if (hf_token) {
                    headers.Authorization = `Bearer ${hf_token}`;
                }

                let response: Response;

                if (semiver(config.version || "2.0.0", "3.30") < 0) {
                    response = await fetch_implementation("https://gradio-space-api-fetcher-v2.hf.space/api", {
                        method: "POST",

                        body: JSON.stringify({
                            serialize: false,
                            config: JSON.stringify(config)
                        }),

                        headers
                    });
                } else {
                    response = await fetch_implementation(`${config.root}/info`, {
                        headers
                    });
                }

                if (!response.ok) {
                    throw new Error(BROKEN_CONNECTION_MSG);
                }

                let api_info = (await response.json()) as ApiInfo<ApiData> | {
                    api: ApiInfo<ApiData>;
                };

                if ("api" in api_info) {
                    api_info = api_info.api;
                }

                if (api_info.named_endpoints["/predict"] && !api_info.unnamed_endpoints["0"]) {
                    api_info.unnamed_endpoints[0] = api_info.named_endpoints["/predict"];
                }

                const x = transform_api_info(api_info, config, api_map);
                return x;
            }
        });
    }

    async function handle_blob(
        endpoint: string,
        data: unknown[],
        api_info: ApiInfo<JsApiData>,
        token?: `hf_${string}`
    ): Promise<unknown[]> {
        const blob_refs = await walk_and_store_blobs(data, undefined, [], true, api_info);

        return Promise.all(blob_refs.map(async (
            {
                path,
                blob,
                type
            }
        ) => {
            if (blob) {
                const file_url = (await upload_files(endpoint, [blob], token)).files[0];

                return {
                    path,
                    file_url,
                    type,
                    name: blob?.name
                };
            }

            return {
                path,
                type
            };
        })).then(r => {
            r.forEach((
                {
                    path,
                    file_url,
                    type,
                    name
                }
            ) => {
                if (type === "Gallery") {
                    update_object(data, file_url, path);
                } else if (file_url) {
                    const file = new FileData({
                        path: file_url,
                        orig_name: name
                    });

                    update_object(data, file, path);
                }
            });

            return data;
        });
    }
}

function api_factory(
    fetch_implementation: typeof fetch,
    EventSource_factory: (url: URL) => EventSource
): Client {
    return {
        post_data,
        upload_files,
        client,
        handle_blob
    };

    async function post_data(url: string, body: unknown, token?: `hf_${string}`): Promise<[PostResponse, number]> {
        const headers: {
            Authorization?: string;
            "Content-Type": "application/json";
        } = {
            "Content-Type": "application/json"
        };

        if (token) {
            headers.Authorization = `Bearer ${token}`;
        }

        try {
            var response = await fetch_implementation(url, {
                method: "POST",
                body: JSON.stringify(body),
                headers
            });
        } catch (e) {
            return [{
                error: BROKEN_CONNECTION_MSG
            }, 500];
        }

        const output: PostResponse = await response.json();
        return [output, response.status];
    }

    async function upload_files(
        root: string,
        files: (Blob | File)[],
        token?: `hf_${string}`,
        upload_id?: string
    ): Promise<UploadResponse> {
        const headers: {
            Authorization?: string;
        } = {};

        if (token) {
            headers.Authorization = `Bearer ${token}`;
        }

        const chunkSize = 1000;
        const uploadResponses = [];

        for (let i = 0; i < files.length; i += chunkSize) {
            const chunk = files.slice(i, i + chunkSize);
            const formData = new FormData();

            chunk.forEach(file => {
                formData.append("files", file);
            });

            try {
                const upload_url = upload_id ? `${root}/upload?upload_id=${upload_id}` : `${root}/upload`;

                var response = await fetch_implementation(upload_url, {
                    method: "POST",
                    body: formData,
                    headers
                });
            } catch (e) {
                return {
                    error: BROKEN_CONNECTION_MSG
                };
            }

            const output: UploadResponse["files"] = await response.json();
            uploadResponses.push(...output);
        }

        return {
            files: uploadResponses
        };
    }

    async function client(
        app_reference: string,
        options: {
            hf_token?: `hf_${string}`;
            status_callback?: SpaceStatusCallback;
            normalise_files?: boolean;
        } = {
            normalise_files: true
        }
    ): Promise<client_return> {
        return new Promise(async res => {
            const {
                status_callback,
                hf_token,
                normalise_files
            } = options;

            const return_obj = {
                predict,
                submit,
                view_api,
                component_server
            };

            const transform_files = normalise_files ?? true;

            if ((typeof window === "undefined" || !("WebSocket" in window)) && !global.Websocket) {
                const ws = await import("ws");
                NodeBlob = (await import("node:buffer")).Blob;
                global.WebSocket = ws.WebSocket;
            }

            const {
                ws_protocol,
                http_protocol,
                host,
                space_id
            } = await process_endpoint(app_reference, hf_token);

            const session_hash = Math.random().toString(36).substring(2);
            const last_status: Record<string, Status["stage"]> = {};
            let stream_open = false;
            let event_stream: EventSource | null = null;
            const event_callbacks: Record<string, () => Promise<void>> = {};
            let config: Config;
            let api_map: Record<string, number> = {};
            let jwt: false | string = false;

            if (hf_token && space_id) {
                jwt = await get_jwt(space_id, hf_token);
            }

            async function config_success(_config: Config): Promise<client_return> {
                config = _config;
                api_map = map_names_to_ids(_config?.dependencies || []);

                if (config.auth_required) {
                    return {
                        config,
                        ...return_obj
                    };
                }

                try {
                    api = await view_api(config);
                } catch (e) {
                    console.error(`Could not get api details: ${e.message}`);
                }

                return {
                    config,
                    ...return_obj
                };
            }

            let api: ApiInfo<JsApiData>;

            async function handle_space_sucess(status: SpaceStatus): Promise<void> {
                if (status_callback)
                    status_callback(status);

                if (status.status === "running") try {
                    config = await resolve_config(fetch_implementation, `${http_protocol}//${host}`, hf_token);
                    const _config = await config_success(config);
                    res(_config);
                } catch (e) {
                    console.error(e);

                    if (status_callback) {
                        status_callback({
                            status: "error",
                            message: "Could not load this space.",
                            load_status: "error",
                            detail: "NOT_FOUND"
                        });
                    }
                }
            }

            try {
                config = await resolve_config(fetch_implementation, `${http_protocol}//${host}`, hf_token);
                const _config = await config_success(config);
                res(_config);
            } catch (e) {
                console.error(e);

                if (space_id) {
                    check_space_status(
                        space_id,
                        RE_SPACE_NAME.test(space_id) ? "space_name" : "subdomain",
                        handle_space_sucess
                    );
                } else {
                    if (status_callback) status_callback({
                        status: "error",
                        message: "Could not load this space.",
                        load_status: "error",
                        detail: "NOT_FOUND"
                    });
                }
            }

            function predict(endpoint: string, data: unknown[], event_data?: unknown): Promise<unknown> {
                let data_returned = false;
                let status_complete = false;
                let dependency;

                if (typeof endpoint === "number") {
                    dependency = config.dependencies[endpoint];
                } else {
                    const trimmed_endpoint = endpoint.replace(/^\//, "");
                    dependency = config.dependencies[api_map[trimmed_endpoint]];
                }

                if (dependency.types.continuous) {
                    throw new Error(
                        "Cannot call predict on this function as it may run forever. Use submit instead"
                    );
                }

                return new Promise((res, rej) => {
                    const app = submit(endpoint, data, event_data);
                    let result;

                    app.on("data", d => {
                        if (status_complete) {
                            app.destroy();
                            res(d);
                        }

                        data_returned = true;
                        result = d;
                    }).on("status", status => {
                        if (status.stage === "error")
                            rej(status);

                        if (status.stage === "complete") {
                            status_complete = true;

                            if (data_returned) {
                                app.destroy();
                                res(result);
                            }
                        }
                    });
                });
            }

            function submit(
                endpoint: string | number,
                data: unknown[],
                event_data?: unknown,
                trigger_id: number | null = null
            ): SubmitReturn {
                let fn_index: number;
                let api_info;

                if (typeof endpoint === "number") {
                    fn_index = endpoint;
                    api_info = api.unnamed_endpoints[fn_index];
                } else {
                    const trimmed_endpoint = endpoint.replace(/^\//, "");
                    fn_index = api_map[trimmed_endpoint];
                    api_info = api.named_endpoints[endpoint.trim()];
                }

                if (typeof fn_index !== "number") {
                    throw new Error(
                        "There is no endpoint matching that name of fn_index matching that number."
                    );
                }

                let websocket: WebSocket;
                let eventSource: EventSource;
                const protocol = config.protocol ?? "ws";
                const _endpoint = typeof endpoint === "number" ? "/predict" : endpoint;
                let payload: Payload;
                let event_id: string | null = null;
                let complete: false | Record<string, any> = false;
                const listener_map: ListenerMap<EventType> = {};
                let url_params = "";

                if (typeof window !== "undefined") {
                    url_params = new URLSearchParams(window.location.search).toString();
                }

                handle_blob(
                    `${http_protocol}//${resolve_root(host, config.path, true)}`,
                    data,
                    api_info,
                    hf_token
                ).then(_payload => {
                    payload = {
                        data: _payload || [],
                        event_data,
                        fn_index,
                        trigger_id
                    };

                    if (skip_queue(fn_index, config)) {
                        fire_event({
                            type: "status",
                            endpoint: _endpoint,
                            stage: "pending",
                            queue: false,
                            fn_index,
                            time: new Date()
                        });

                        post_data(
                            `${http_protocol}//${resolve_root(host, config.path, true)}/run${_endpoint.startsWith("/") ? _endpoint : `/${_endpoint}`}${url_params ? "?" + url_params : ""}`,
                            {
                                ...payload,
                                session_hash
                            },
                            hf_token
                        ).then(([output, status_code]) => {
                            const data = transform_files ? transform_output(output.data, api_info, config.root, config.root_url) : output.data;

                            if (status_code == 200) {
                                fire_event({
                                    type: "data",
                                    endpoint: _endpoint,
                                    fn_index,
                                    data: data,
                                    time: new Date()
                                });

                                fire_event({
                                    type: "status",
                                    endpoint: _endpoint,
                                    fn_index,
                                    stage: "complete",
                                    eta: output.average_duration,
                                    queue: false,
                                    time: new Date()
                                });
                            } else {
                                fire_event({
                                    type: "status",
                                    stage: "error",
                                    endpoint: _endpoint,
                                    fn_index,
                                    message: output.error,
                                    queue: false,
                                    time: new Date()
                                });
                            }
                        }).catch(e => {
                            fire_event({
                                type: "status",
                                stage: "error",
                                message: e.message,
                                endpoint: _endpoint,
                                fn_index,
                                queue: false,
                                time: new Date()
                            });
                        });
                    } else if (protocol == "ws") {
                        fire_event({
                            type: "status",
                            stage: "pending",
                            queue: true,
                            endpoint: _endpoint,
                            fn_index,
                            time: new Date()
                        });

                        const url = new URL(`${ws_protocol}://${resolve_root(host, config.path, true)}
                            /queue/join${url_params ? "?" + url_params : ""}`);

                        if (jwt) {
                            url.searchParams.set("__sign", jwt);
                        }

                        websocket = new WebSocket(url);

                        websocket.onclose = evt => {
                            if (!evt.wasClean) {
                                fire_event({
                                    type: "status",
                                    stage: "error",
                                    broken: true,
                                    message: BROKEN_CONNECTION_MSG,
                                    queue: true,
                                    endpoint: _endpoint,
                                    fn_index,
                                    time: new Date()
                                });
                            }
                        };

                        websocket.onmessage = function(event) {
                            const _data = JSON.parse(event.data);

                            const {
                                type,
                                status,
                                data
                            } = handle_message(_data, last_status[fn_index]);

                            if (type === "update" && status && !complete) {
                                fire_event({
                                    type: "status",
                                    endpoint: _endpoint,
                                    fn_index,
                                    time: new Date(),
                                    ...status
                                });

                                if (status.stage === "error") {
                                    websocket.close();
                                }
                            } else if (type === "hash") {
                                websocket.send(JSON.stringify({
                                    fn_index,
                                    session_hash
                                }));

                                return;
                            } else if (type === "data") {
                                websocket.send(JSON.stringify({
                                    ...payload,
                                    session_hash
                                }));
                            } else if (type === "complete") {
                                complete = status;
                            } else if (type === "log") {
                                fire_event({
                                    type: "log",
                                    log: data.log,
                                    level: data.level,
                                    endpoint: _endpoint,
                                    fn_index
                                });
                            } else if (type === "generating") {
                                fire_event({
                                    type: "status",
                                    time: new Date(),
                                    ...status,
                                    stage: status?.stage!,
                                    queue: true,
                                    endpoint: _endpoint,
                                    fn_index
                                });
                            }

                            if (data) {
                                fire_event({
                                    type: "data",
                                    time: new Date(),
                                    data: transform_files ? transform_output(data.data, api_info, config.root, config.root_url) : data.data,
                                    endpoint: _endpoint,
                                    fn_index
                                });

                                if (complete) {
                                    fire_event({
                                        type: "status",
                                        time: new Date(),
                                        ...complete,
                                        stage: status?.stage!,
                                        queue: true,
                                        endpoint: _endpoint,
                                        fn_index
                                    });

                                    websocket.close();
                                }
                            }
                        };

                        if (semiver(config.version || "2.0.0", "3.6") < 0) {
                            addEventListener("open", () => websocket.send(JSON.stringify({
                                hash: session_hash
                            })));
                        }
                    } else if (protocol == "sse") {
                        fire_event({
                            type: "status",
                            stage: "pending",
                            queue: true,
                            endpoint: _endpoint,
                            fn_index,
                            time: new Date()
                        });

                        const params = new URLSearchParams({
                            fn_index: fn_index.toString(),
                            session_hash: session_hash
                        }).toString();

                        const url = new URL(
                            `${http_protocol}//${resolve_root(host, config.path, true)}/queue/join?${url_params ? url_params + "&" : ""}${params}`
                        );

                        eventSource = EventSource_factory(url);

                        eventSource.onmessage = async function(event) {
                            const _data = JSON.parse(event.data);

                            const {
                                type,
                                status,
                                data
                            } = handle_message(_data, last_status[fn_index]);

                            if (type === "update" && status && !complete) {
                                fire_event({
                                    type: "status",
                                    endpoint: _endpoint,
                                    fn_index,
                                    time: new Date(),
                                    ...status
                                });

                                if (status.stage === "error") {
                                    eventSource.close();
                                }
                            } else if (type === "data") {
                                event_id = _data.event_id as string;

                                const [_, status] = await post_data(`${http_protocol}//${resolve_root(host, config.path, true)}/queue/data`, {
                                    ...payload,
                                    session_hash,
                                    event_id
                                }, hf_token);

                                if (status !== 200) {
                                    fire_event({
                                        type: "status",
                                        stage: "error",
                                        message: BROKEN_CONNECTION_MSG,
                                        queue: true,
                                        endpoint: _endpoint,
                                        fn_index,
                                        time: new Date()
                                    });

                                    eventSource.close();
                                }
                            } else if (type === "complete") {
                                complete = status;
                            } else if (type === "log") {
                                fire_event({
                                    type: "log",
                                    log: data.log,
                                    level: data.level,
                                    endpoint: _endpoint,
                                    fn_index
                                });
                            } else if (type === "generating") {
                                fire_event({
                                    type: "status",
                                    time: new Date(),
                                    ...status,
                                    stage: status?.stage!,
                                    queue: true,
                                    endpoint: _endpoint,
                                    fn_index
                                });
                            }

                            if (data) {
                                fire_event({
                                    type: "data",
                                    time: new Date(),
                                    data: transform_files ? transform_output(data.data, api_info, config.root, config.root_url) : data.data,
                                    endpoint: _endpoint,
                                    fn_index
                                });

                                if (complete) {
                                    fire_event({
                                        type: "status",
                                        time: new Date(),
                                        ...complete,
                                        stage: status?.stage!,
                                        queue: true,
                                        endpoint: _endpoint,
                                        fn_index
                                    });

                                    eventSource.close();
                                }
                            }
                        };
                    } else if (protocol == "sse_v1") {
                        fire_event({
                            type: "status",
                            stage: "pending",
                            queue: true,
                            endpoint: _endpoint,
                            fn_index,
                            time: new Date()
                        });

                        post_data(
                            `${http_protocol}//${resolve_root(host, config.path, true)}/queue/join?${url_params}`,
                            {
                                ...payload,
                                session_hash
                            },
                            hf_token
                        ).then(([response, status]) => {
                            if (status !== 200) {
                                fire_event({
                                    type: "status",
                                    stage: "error",
                                    message: BROKEN_CONNECTION_MSG,
                                    queue: true,
                                    endpoint: _endpoint,
                                    fn_index,
                                    time: new Date()
                                });
                            } else {
                                event_id = response.event_id as string;

                                if (!stream_open) {
                                    open_stream();
                                }

                                const callback = async function(_data: object): void {
                                    const {
                                        type,
                                        status,
                                        data
                                    } = handle_message(_data, last_status[fn_index]);

                                    if (type === "update" && status && !complete) {
                                        fire_event({
                                            type: "status",
                                            endpoint: _endpoint,
                                            fn_index,
                                            time: new Date(),
                                            ...status
                                        });
                                    } else if (type === "complete") {
                                        complete = status;
                                    } else if (type === "log") {
                                        fire_event({
                                            type: "log",
                                            log: data.log,
                                            level: data.level,
                                            endpoint: _endpoint,
                                            fn_index
                                        });
                                    } else if (type === "generating") {
                                        fire_event({
                                            type: "status",
                                            time: new Date(),
                                            ...status,
                                            stage: status?.stage!,
                                            queue: true,
                                            endpoint: _endpoint,
                                            fn_index
                                        });
                                    }

                                    if (data) {
                                        fire_event({
                                            type: "data",
                                            time: new Date(),
                                            data: transform_files ? transform_output(data.data, api_info, config.root, config.root_url) : data.data,
                                            endpoint: _endpoint,
                                            fn_index
                                        });

                                        if (complete) {
                                            fire_event({
                                                type: "status",
                                                time: new Date(),
                                                ...complete,
                                                stage: status?.stage!,
                                                queue: true,
                                                endpoint: _endpoint,
                                                fn_index
                                            });
                                        }
                                    }

                                    if (status.stage === "complete" || status.stage === "error") {
                                        if (event_callbacks[event_id]) {
                                            delete event_callbacks[event_id];

                                            if (Object.keys(event_callbacks).length === 0) {
                                                close_stream();
                                            }
                                        }
                                    }
                                };

                                event_callbacks[event_id] = callback;
                            }
                        });
                    }
                });

                function fire_event<K extends EventType>(event: Event<K>): void {
                    const narrowed_listener_map: ListenerMap<K> = listener_map;
                    const listeners = narrowed_listener_map[event.type] || [];
                    listeners?.forEach(l => l(event));
                }

                function on<K extends EventType>(eventType: K, listener: EventListener<K>): SubmitReturn {
                    const narrowed_listener_map: ListenerMap<K> = listener_map;
                    const listeners = narrowed_listener_map[eventType] || [];
                    narrowed_listener_map[eventType] = listeners;
                    listeners?.push(listener);

                    return {
                        on,
                        off,
                        cancel,
                        destroy
                    };
                }

                function off<K extends EventType>(eventType: K, listener: EventListener<K>): SubmitReturn {
                    const narrowed_listener_map: ListenerMap<K> = listener_map;
                    let listeners = narrowed_listener_map[eventType] || [];
                    listeners = listeners?.filter(l => l !== listener);
                    narrowed_listener_map[eventType] = listeners;

                    return {
                        on,
                        off,
                        cancel,
                        destroy
                    };
                }

                async function cancel(): Promise<void> {
                    const _status: Status = {
                        stage: "complete",
                        queue: false,
                        time: new Date()
                    };

                    complete = _status;

                    fire_event({
                        ..._status,
                        type: "status",
                        endpoint: _endpoint,
                        fn_index: fn_index
                    });

                    let cancel_request = {};

                    if (protocol === "ws") {
                        if (websocket && websocket.readyState === 0) {
                            websocket.addEventListener("open", () => {
                                websocket.close();
                            });
                        } else {
                            websocket.close();
                        }

                        cancel_request = {
                            fn_index,
                            session_hash
                        };
                    } else {
                        eventSource.close();

                        cancel_request = {
                            event_id
                        };
                    }

                    try {
                        await fetch_implementation(`${http_protocol}//${resolve_root(host, config.path, true)}/reset`, {
                            headers: {
                                "Content-Type": "application/json"
                            },

                            method: "POST",
                            body: JSON.stringify(cancel_request)
                        });
                    } catch (e) {
                        console.warn(
                            "The `/reset` endpoint could not be called. Subsequent endpoint results may be unreliable."
                        );
                    }
                }

                function destroy(): void {
                    for (const event_type in listener_map) {
                        listener_map[event_type as "data" | "status"].forEach(fn => {
                            off(event_type as "data" | "status", fn);
                        });
                    }
                }

                return {
                    on,
                    off,
                    cancel,
                    destroy
                };
            }

            function open_stream(): void {
                stream_open = true;

                const params = new URLSearchParams({
                    session_hash: session_hash
                }).toString();

                const url = new URL(
                    `${http_protocol}//${resolve_root(host, config.path, true)}/queue/data?${params}`
                );

                event_stream = new EventSource(url);

                event_stream.onmessage = async function(event) {
                    const _data = JSON.parse(event.data);
                    await event_callbacks[_data.event_id](_data);
                };
            }

            function close_stream(): void {
                stream_open = false;
                event_stream?.close();
            }

            async function component_server(component_id: number, fn_name: string, data: unknown[]): Promise<any> {
                const headers: {
                    Authorization?: string;
                    "Content-Type": "application/json";
                } = {
                    "Content-Type": "application/json"
                };

                if (hf_token) {
                    headers.Authorization = `Bearer ${hf_token}`;
                }

                let root_url: string;
                const component = config.components.find(comp => comp.id === component_id);

                if (component?.props?.root_url) {
                    root_url = component.props.root_url;
                } else {
                    root_url = `${http_protocol}//${resolve_root(host, config.path, true)}/`;
                }

                const response = await fetch_implementation(`${root_url}component_server/`, {
                    method: "POST",

                    body: JSON.stringify({
                        data: data,
                        component_id: component_id,
                        fn_name: fn_name,
                        session_hash: session_hash
                    }),

                    headers
                });

                if (!response.ok) {
                    throw new Error("Could not connect to component server: " + response.statusText);
                }

                const output = await response.json();
                return output;
            }

            async function view_api(config?: Config): Promise<ApiInfo<JsApiData>> {
                if (api)
                    return api;

                const headers: {
                    Authorization?: string;
                    "Content-Type": "application/json";
                } = {
                    "Content-Type": "application/json"
                };

                if (hf_token) {
                    headers.Authorization = `Bearer ${hf_token}`;
                }

                let response: Response;

                if (semiver(config.version || "2.0.0", "3.30") < 0) {
                    response = await fetch_implementation("https://gradio-space-api-fetcher-v2.hf.space/api", {
                        method: "POST",

                        body: JSON.stringify({
                            serialize: false,
                            config: JSON.stringify(config)
                        }),

                        headers
                    });
                } else {
                    response = await fetch_implementation(`${config.root}/info`, {
                        headers
                    });
                }

                if (!response.ok) {
                    throw new Error(BROKEN_CONNECTION_MSG);
                }

                let api_info = (await response.json()) as ApiInfo<ApiData> | {
                    api: ApiInfo<ApiData>;
                };

                if ("api" in api_info) {
                    api_info = api_info.api;
                }

                if (api_info.named_endpoints["/predict"] && !api_info.unnamed_endpoints["0"]) {
                    api_info.unnamed_endpoints[0] = api_info.named_endpoints["/predict"];
                }

                const x = transform_api_info(api_info, config, api_map);
                return x;
            }
        });
    }

    async function handle_blob(
        endpoint: string,
        data: unknown[],
        api_info: ApiInfo<JsApiData>,
        token?: `hf_${string}`
    ): Promise<unknown[]> {
        const blob_refs = await walk_and_store_blobs(data, undefined, [], true, api_info);

        return Promise.all(blob_refs.map(async (
            {
                path,
                blob,
                type
            }
        ) => {
            if (blob) {
                const file_url = (await upload_files(endpoint, [blob], token)).files[0];

                return {
                    path,
                    file_url,
                    type,
                    name: blob?.name
                };
            }

            return {
                path,
                type
            };
        })).then(r => {
            r.forEach((
                {
                    path,
                    file_url,
                    type,
                    name
                }
            ) => {
                if (type === "Gallery") {
                    update_object(data, file_url, path);
                } else if (file_url) {
                    const file = new FileData({
                        path: file_url,
                        orig_name: name
                    });

                    update_object(data, file, path);
                }
            });

            return data;
        });
    }
}

(
    destination: Record<string, unknown>,
    ...sources: Record<string, unknown>[]
): Record<string, unknown> => {
    const result = destination;

    if (!isIterable(result)) {
        return result;
    }

    for (const src of sources) {
        for (const key in src) {
            if (isIterable(src[key])) {
                if (!result[key]) {
                    result[key] = {};
                }

                mergeDeep(
                    result[key] as Record<string, unknown>,
                    src[key] as Record<string, unknown>
                );
            } else if (!isNullish(src[key]) && Object.hasOwnProperty.call(src, key)) {
                if (Array.isArray(src[key]) || src[key] instanceof TypedArray) {
                    result[key] = (src[key] as unknown[]).slice(0);
                } else {
                    result[key] = src[key];
                }
            }
        }
    }

    return result;
}

(
    destination: Record<string, unknown>,
    ...sources: Record<string, unknown>[]
): Record<string, unknown> => {
    const result = {
        ...destination
    };

    if (!isIterable(result)) {
        return result;
    }

    for (const src of sources) {
        for (const key in src) {
            if (isIterable(src[key])) {
                if (!result[key]) {
                    result[key] = {};
                }

                mergeDeep(
                    result[key] as Record<string, unknown>,
                    src[key] as Record<string, unknown>
                );
            } else if (!isNullish(src[key]) && Object.hasOwnProperty.call(src, key)) {
                if (Array.isArray(src[key]) || src[key] instanceof TypedArray) {
                    result[key] = (src[key] as unknown[]).slice(0);
                } else {
                    result[key] = src[key];
                }
            }
        }
    }

    return result;
}

(event: APIGatewayProxyEvent) => {
    const {
