async function dumpENV() {
    const fs = require("fs");
    const path = require("path");
    const frozenEnvs = {};

    const protectedKeys = [
        ...Object.values(KEY_MAPPING).map(values => values.envKey),
        "STORAGE_DIR",
        "SERVER_PORT",
        "PASSWORDMINCHAR",
        "PASSWORDMAXCHAR",
        "PASSWORDLOWERCASE",
        "PASSWORDUPPERCASE",
        "PASSWORDNUMERIC",
        "PASSWORDSYMBOL",
        "PASSWORDREQUIREMENTS",
        "ENABLE_HTTPS",
        "HTTPS_CERT_PATH",
        "HTTPS_KEY_PATH",
        "DISABLE_TELEMETRY"
    ];

    for (const key of protectedKeys) {
        const envValue = process.env?.[key] || null;

        if (!envValue)
            continue;

        frozenEnvs[key] = process.env?.[key] || null;
    }

    let envResult = `# Auto-dump ENV from system call on ${new Date().toTimeString()}\n`;

    envResult += Object.entries(frozenEnvs).map(([key, value]) => {
        return `${key}='${value}'`;
    }).join("\n");

    const envPath = path.join(__dirname, "../../.env");

    fs.writeFileSync(envPath, envResult, {
        encoding: "utf8",
        flag: "w"
    });

    return true;
}

async function dumpENV() {
    const fs = require("fs");
    const path = require("path");
    const frozenEnvs = {};

    const protectedKeys = [
        ...Object.values(KEY_MAPPING).map(values => values.envKey),
        "STORAGE_DIR",
        "SERVER_PORT",
        "PASSWORDMINCHAR",
        "PASSWORDMAXCHAR",
        "PASSWORDLOWERCASE",
        "PASSWORDUPPERCASE",
        "PASSWORDNUMERIC",
        "PASSWORDSYMBOL",
        "PASSWORDREQUIREMENTS",
        "ENABLE_HTTPS",
        "HTTPS_CERT_PATH",
        "HTTPS_KEY_PATH",
        "DISABLE_TELEMETRY"
    ];

    function sanitizeValue(value) {
        const offendingChars = /[\n\r\t\v\f\u0085\u00a0\u1680\u180e\u2000-\u200a\u2028\u2029\u202f\u205f\u3000"'`#]/;
        const firstOffendingCharIndex = value.search(offendingChars);

        if (firstOffendingCharIndex === -1)
            return value;

        return value.substring(0, firstOffendingCharIndex);
    }

    for (const key of protectedKeys) {
        const envValue = process.env?.[key] || null;

        if (!envValue)
            continue;

        frozenEnvs[key] = process.env?.[key] || null;
    }

    let envResult = `# Auto-dump ENV from system call on ${new Date().toTimeString()}\n`;
    envResult += Object.entries(frozenEnvs).map(([key, value]) => `${key}='${sanitizeValue(value)}'`).join("\n");
    const envPath = path.join(__dirname, "../../.env");

    fs.writeFileSync(envPath, envResult, {
        encoding: "utf8",
        flag: "w"
    });

    return true;
}

function normalizePath(filepath = "") {
    const result = path.normalize(filepath.trim()).replace(/^(\.\.(\/|\\|$))+/, "").trim();

    if (["..", ".", "/"].includes(result))
        throw new Error("Invalid path.");

    return result;
}

