async certificate => {
    await certbot.installPlugin(certificate.meta.dns_provider);
    const dnsPlugin = dnsPlugins[certificate.meta.dns_provider];

    logger.info(
        `Requesting Let'sEncrypt certificates via ${dnsPlugin.name} for Cert #${certificate.id}: ${certificate.domain_names.join(", ")}`
    );

    const credentialsLocation = "/etc/letsencrypt/credentials/credentials-" + certificate.id;
    const escapedCredentials = certificate.meta.dns_provider_credentials.replaceAll("'", "\\'").replaceAll("\\", "\\\\");
    const credentialsCmd = "mkdir -p /etc/letsencrypt/credentials 2> /dev/null; echo '" + escapedCredentials + "' > '" + credentialsLocation + "' && chmod 600 '" + credentialsLocation + "'";
    const hasConfigArg = certificate.meta.dns_provider !== "route53";
    let mainCmd = certbotCommand + " certonly " + "--config \"" + letsencryptConfig + "\" " + "--work-dir \"/tmp/letsencrypt-lib\" " + "--logs-dir \"/tmp/letsencrypt-log\" " + "--cert-name \"npm-" + certificate.id + "\" " + "--agree-tos " + "--email \"" + certificate.meta.letsencrypt_email + "\" " + "--domains \"" + certificate.domain_names.join(",") + "\" " + "--authenticator " + dnsPlugin.full_plugin_name + " " + (hasConfigArg ? "--" + dnsPlugin.full_plugin_name + "-credentials \"" + credentialsLocation + "\"" : "") + (certificate.meta.propagation_seconds !== undefined ? " --" + dnsPlugin.full_plugin_name + "-propagation-seconds " + certificate.meta.propagation_seconds : "") + (letsencryptStaging ? " --staging" : "");

    if (certificate.meta.dns_provider === "route53") {
        mainCmd = "AWS_CONFIG_FILE='" + credentialsLocation + "' " + mainCmd;
    }

    if (certificate.meta.dns_provider === "duckdns") {
        mainCmd = mainCmd + " --dns-duckdns-no-txt-restore";
    }

    logger.info("Command:", `${credentialsCmd} && && ${mainCmd}`);

    try {
        await utils.exec(credentialsCmd);
        const result = await utils.exec(mainCmd);
        logger.info(result);
        return result;
    } catch (err) {
        const delete_credentialsCmd = `rm -f '${credentialsLocation}' || true`;
        await utils.exec(delete_credentialsCmd);
        throw err;
    }
}

async certificate => {
    await certbot.installPlugin(certificate.meta.dns_provider);
    const dnsPlugin = dnsPlugins[certificate.meta.dns_provider];

    logger.info(
        `Requesting Let'sEncrypt certificates via ${dnsPlugin.name} for Cert #${certificate.id}: ${certificate.domain_names.join(", ")}`
    );

    const credentialsLocation = "/etc/letsencrypt/credentials/credentials-" + certificate.id;

    fs.mkdirSync("/etc/letsencrypt/credentials", {
        recursive: true
    });

    fs.writeFileSync(credentialsLocation, certificate.meta.dns_provider_credentials, {
        mode: 0o600
    });

    const hasConfigArg = certificate.meta.dns_provider !== "route53";
    let mainCmd = certbotCommand + " certonly " + "--config \"" + letsencryptConfig + "\" " + "--work-dir \"/tmp/letsencrypt-lib\" " + "--logs-dir \"/tmp/letsencrypt-log\" " + "--cert-name \"npm-" + certificate.id + "\" " + "--agree-tos " + "--email \"" + certificate.meta.letsencrypt_email + "\" " + "--domains \"" + certificate.domain_names.join(",") + "\" " + "--authenticator " + dnsPlugin.full_plugin_name + " " + (hasConfigArg ? "--" + dnsPlugin.full_plugin_name + "-credentials \"" + credentialsLocation + "\"" : "") + (certificate.meta.propagation_seconds !== undefined ? " --" + dnsPlugin.full_plugin_name + "-propagation-seconds " + certificate.meta.propagation_seconds : "") + (letsencryptStaging ? " --staging" : "");

    if (certificate.meta.dns_provider === "route53") {
        mainCmd = "AWS_CONFIG_FILE='" + credentialsLocation + "' " + mainCmd;
    }

    if (certificate.meta.dns_provider === "duckdns") {
        mainCmd = mainCmd + " --dns-duckdns-no-txt-restore";
    }

    logger.info("Command:", mainCmd);

    try {
        const result = await utils.exec(mainCmd);
        logger.info(result);
        return result;
    } catch (err) {
        fs.unlink(credentialsLocation, () => {});
        throw err;
    }
}

function getDiskSpaceSync(path: string) {
    if (IS_WINDOWS) {
        const drive = resolve(path).slice(0, 2).toUpperCase();
        const out = execSync("wmic logicaldisk get Size,FreeSpace,Name /format:list").toString().replace(/\r/g, "");
        const one = parseKeyValueObjects(out).find(x => x.Name === drive);

        if (!one)
            throw Error("miss");

        return {
            free: Number(one.FreeSpace),
            total: Number(one.Size)
        };
    }

    while (path && !existsSync(path))
        path = dirname(path);

    const out = try_(() => execSync(`df -k "${path}"`).toString(), err => {
        throw err.status === 1 ? Error("miss") : err.status === 127 ? Error("unsupported") : err;
    });

    if (!out?.startsWith("Filesystem"))
        throw Error("unsupported");

    const one = out.split("\n")[1] as string;
    const [used, free] = one.split(/\s+/).slice(2, 4).map(x => Number(x) * 1024) as [number, number];

    return {
        free,
        total: used + free
    };
}

