    };
}

async (req, res, next) => {
    if (req.method !== "GET" && req.method !== "POST") {
        throw new MethodNotAllowedError({
            allowed: ["GET", "POST"],
            current: req.method
        });
    }

    let query: string | null = null;
    let variables: Record<string, unknown> | null = null;
    let operationName: string | null = null;
    let document: DocumentNode;

    if (req.method === "GET") {
        query = (req.query["query"] as string | undefined) || null;

        if (req.query["variables"]) {
            try {
                variables = parseJSON(req.query["variables"] as string);
            } catch {
                throw new InvalidQueryError({
                    reason: `Variables are invalid JSON`
                });
            }
        } else {
            variables = {};
        }

        operationName = (req.query["operationName"] as string | undefined) || null;
    } else {
        query = req.body.query || null;
        variables = req.body.variables || null;
        operationName = req.body.operationName || null;
    }

    if (query === null) {
        throw new InvalidPayloadError({
            reason: "Must provide query string"
        });
    }

    try {
        document = parse(new Source(query));
    } catch (err: any) {
        throw new GraphQLValidationError({
            errors: [err]
        });
    }

    const operationAST = getOperationAST(document, operationName);

    if (req.method === "GET" && operationAST?.operation !== "query") {
        throw new MethodNotAllowedError({
            allowed: ["POST"],
            current: "GET"
        });
    }

    if (operationAST?.operation === "mutation") {
        res.locals["cache"] = false;
    }

    res.locals["graphqlParams"] = {
        document,
        query,
        variables,
        operationName,

        contextValue: {
            req,
            res
        }
    } as GraphQLParams;

    return next();
}

function handleExtractQueryParamsMiddleware(encryptionService?: StringEncrypter) {
    return async (c: Context<AppEnv>, next: () => Promise<void>) => {
        const params = new URL(c.req.url).searchParams;
        let input: PlainConfigSchema | URLSearchParams;

        if (params.has("hash")) {
            if (!encryptionService) {
                throw new HTTPException(400, {
                    message: "This server is not configured for encryption"
                });
            }

            const hash = params.get("hash");

            if (typeof hash !== "string" || !hash.startsWith("str-enc:")) {
                throw new HTTPException(400, {
                    message: "Invalid hash"
                });
            }

            const decryptedString = await encryptionService.decrypt(hash);
            input = JSON.parse(decryptedString);
        } else {
            if (encryptionService) {
                throw new HTTPException(400, {
                    message: "This server must use encryption"
                });
            }

            input = params;
        }

        const {
            validData,
            errors
        } = parseForm({
            data: input,
            schema: PlainConfigSchema
        });

        if (validData?.viewPortWidth !== undefined) {
            logger.warn("'viewPortWidth' is deprecated, please use 'viewportWidth'");
        }

        if (validData?.viewPortHeight !== undefined) {
            logger.warn("'viewPortHeight' is deprecated, please use 'viewportHeight'");
        }

        if (errors) {
            let message: string = "Invalid query parameters: ";
            const specificErrors = Object.entries(errors).map(([key, value]) => `(${key} - ${value})`).join(" ");
            message = `${message} ${specificErrors}`;

            throw new HTTPException(400, {
                message,
                cause: errors
            });
        }

        if (validData.width && validData.width > 1920) {
            validData.width = 1920;
        }

        if (validData.height && validData.height > 1920) {
            validData.height = 1920;
        }

        const viewportWidth = validData.viewportWidth ?? validData.viewPortWidth;

        if (viewportWidth && viewportWidth > 1920) {
            validData.width = 1920;
        }

        const viewportHeight = validData.viewportHeight ?? validData.viewPortHeight;

        if (viewportHeight && viewportHeight > 1920) {
            validData.width = 1920;
        }

        const date = new Date();
        const dateString = date.toLocaleDateString().replace(/\//g, "-");
        const imageId = dateString + "." + slugify(validData.url) + configToString(params);
        c.set("input", validData);
        c.set("imageId", imageId);
        await next();
    };
}

