async function streamExtractExternal(url: string, directory: string): Promise<void> {
    const client = new httpClient.HttpClient(getUserAgentString());
    const response = await client.get(url);

    if (response.message.statusCode !== 200) {
        throw new Error(
            `Unexpected HTTP response from blob storage: ${response.message.statusCode} ${response.message.statusMessage}`
        );
    }

    const timeout = 30 * 1000;

    return new Promise((resolve, reject) => {
        const timerFn = (): void => {
            response.message.destroy(new Error(`Blob storage chunk did not respond in ${timeout}ms`));
        };

        const timer = setTimeout(timerFn, timeout);

        response.message.on("data", () => {
            timer.refresh();
        }).on("error", (error: Error) => {
            core.debug(`response.message: Artifact download failed: ${error.message}`);
            clearTimeout(timer);
            reject(error);
        }).pipe(unzip.Extract({
            path: directory
