private async getParsedFile(key: string): Promise<Uint8Array | undefined> {
    try {
        const fileContent = await fs.readFile(this.getFullPath(key));

        if (!fileContent) {
            return undefined;
        }

        return fileContent;
    } catch (e: any) {
        if ("code" in e && e.code === "ENOENT") {
            return undefined;
        }

        throw new Error(
            `Error reading and parsing file at path: ${this.rootPath}.\nError: ${JSON.stringify(e)}`
        );
    }
}

private getFullPath(key: string): string {
    try {
        const keyAsTxtFile = `${key}.txt`;
        const fullPath = path.join(this.rootPath, keyAsTxtFile);
        return fullPath;
    } catch (e) {
        throw new Error(`Error getting full path for key: ${key}.\nError: ${JSON.stringify(e)}`);
    }
}

private async getParsedFile(key: string): Promise<Uint8Array | undefined> {
    if (!/^[a-zA-Z0-9_\-:.]+$/.test(key)) {
        throw new Error(
            "Invalid key. Only alphanumeric characters, underscores, hyphens, colons, and periods are allowed."
        );
    }

    try {
        const fileContent = await fs.readFile(this.getFullPath(key));

        if (!fileContent) {
            return undefined;
        }

        return fileContent;
    } catch (e: any) {
        if ("code" in e && e.code === "ENOENT") {
            return undefined;
        }

        throw new Error(
            `Error reading and parsing file at path: ${this.rootPath}.\nError: ${JSON.stringify(e)}`
        );
    }
}

private getFullPath(key: string): string {
    try {
        const keyAsTxtFile = `${key}.txt`;

        if (!/^[a-zA-Z0-9_.\-/]+$/.test(key)) {
            throw new Error(`Invalid characters in key: ${key}`);
        }

        const fullPath = path.resolve(this.rootPath, keyAsTxtFile);
        const commonPath = path.resolve(this.rootPath);

        if (!fullPath.startsWith(commonPath)) {
            throw new Error(
                `Invalid key: ${key}. Key should be relative to the root path. ` + `Root path: ${this.rootPath}, Full path: ${fullPath}`
            );
        }

        return fullPath;
    } catch (e) {
        throw new Error(`Error getting full path for key: ${key}.\nError: ${String(e)}`);
    }
}

function clone(object) {
    const newObject = create(null);
    let property;

    for (property in object) {
        if (apply(hasOwnProperty, object, [property])) {
            newObject[property] = object[property];
        }
    }

    return newObject;
}

